window.QUESTION_BANK = [{"id":1,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"马克思主义要在中国大地上闪耀真理光芒,就必须( )。","options":{"A":"革命化","B":"政治化","C":"中国化","D":"学术化"},"answer":"C","order":1,"explanation":"马克思主义要在中国发挥指导作用，就必须中国化。应把马克思主义基本原理同中国具体实际结合起来，运用它的立场、观点和方法解决中国革命、建设和改革中的实际问题。","note":""},{"id":2,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"( )的召开,实现了新中国成立以来党的历史上具有深远意义的伟大转折,开启了改革开放和社会主义现代化建设历史新时期","options":{"A":"中共十一届三中全会","B":"中共十二大","C":"中共十三大","D":"中共十一届六中全会"},"answer":"A","order":2,"explanation":"1978年12月召开的党的十一届三中全会，做出了实行改革开放的重大决策。","note":""},{"id":3,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"习近平新时代中国特色社会思想从理论和实践结合系统回了新时代( )这个重大时代课题。","options":{"A":"新理念、新思想、新战略","B":"坚持和发展什么样的中国特色社会主义,怎样坚持和发展中国特色社会主义","C":"中国梦","D":"实现什么样的发展,怎样发展"},"answer":"B","order":3,"explanation":"坚持和发展中国特色社会主义，是改革开放以来我们党全部理论和实践的鲜明主题，也是习近平新时代中国特色社会主义思想的核心要义。\n对应本题，应完整回答：新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义。","note":""},{"id":4,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"第一次提出“马克思主义中国化”的会议是( )","options":{"A":"中共二大","B":"中共四大","C":"党的六届六中全会","D":"中共七大"},"answer":"C","order":4,"explanation":"1938年，毛泽东在党的六届六中全会上作《论新阶段》的报告，首次明确提出“马克思主义中国化”这一命题。记忆要素为1938年、毛泽东、六届六中全会和《论新阶段》。","note":""},{"id":5,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"科学发展观深刻的认识和回答了( )等重大问题,形成了以人为本,全面协调可持续的科学发展观。","options":{"A":"发展生产力","B":"改革开放","C":"什么是社会主义,怎样建设社会主义","D":"实现什么样的发展,怎样发展"},"answer":"D","order":5,"explanation":"科学发展观，第一要义是发展，核心立场是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾。\n科学发展观深刻认识和回答了“实现什么样的发展、怎样发展”等重大问题。","note":""},{"id":6,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"马克思主义中国化第一次历史性飞跃发生在( )。","options":{"A":"社会主义建设时期","B":"从新民主主义向社会主义过渡时期","C":"新民主主义革命时期","D":"旧民主主义革命时期"},"answer":"C","order":6,"explanation":"第一次历史性飞跃发生在新民主主义革命时期，形成了毛泽东思想。","note":"本题沿用课程题库的“两次历史性飞跃”口径。新民主主义革命时期一般指1919年至1949年，不能把整个飞跃简单等同于某一年。"},{"id":7,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"马克思主义中国化,就是将( )。","options":{"A":"中国革命进程中正反两方面的实践经验进行科学总结","B":"毛泽东思想作为我们党一切工作的指南","C":"马克思主义作为一种外来思想文化传入中国","D":"马克思主义基本原理同中国具体实践相结合"},"answer":"D","order":7,"explanation":"马克思主义中国化，就是把马克思主义基本原理同中国具体实际相结合，运用马克思主义的立场、观点和方法研究、解决中国实际问题，并把实践经验提升为具有中国特色的理论成果。","note":""},{"id":8,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"1938年，（）在党的六届六中全会上作了《论新阶段》的报告，强调：“没有抽象的马克思主义，只有具体的马克思主义……”","options":{"A":"毛泽东","B":"任弼时","C":"刘少奇","D":"周恩来"},"answer":"A","order":8,"explanation":"1938年，毛泽东在党的六届六中全会上作《论新阶段》的报告，强调没有抽象的马克思主义，只有具体的马克思主义，要求把马克思主义同中国具体实际相结合。","note":""},{"id":9,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"中国化了的马克思主义不包括( )。","options":{"A":"毛泽东思想","B":"中国特色社会主义理论","C":"马克思列宁主义","D":"中华民族的优秀思想"},"answer":"C","order":9,"explanation":"第二次历史性飞跃发生在社会主义进入改革开放的新时期，形成了包括邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想在内的中国特色社会主义理论体系。\n马克思列宁主义是理论来源和指导思想，不能直接等同于马克思主义中国化所形成的理论成果；毛泽东思想是马克思主义中国化的第一个重大理论成果。","note":"原题答案为C，但选项“中华民族的优秀思想”也不能整体直接等同于中国化的马克思主义，原单选题存在表述歧义。本网站按原题答案判分。"},{"id":10,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"1921年中国共产党诞生后,( )成为中国共产党人的重大时代课题。","options":{"A":"领导工人运动","B":"遵循马克思列宁主义","C":"“马克思主义中国化”","D":"领导中国革命"},"answer":"C","order":10,"explanation":"1921年中国共产党成立后，如何把马克思主义基本原理同中国具体实际相结合，推进马克思主义中国化，成为中国共产党人的重大时代课题。","note":""},{"id":11,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"“三个代表”重要思想,进一步回答了什么是社会主义,怎样建设社会主义,又创造性的回答了( )的问题。","options":{"A":"如何发展","B":"建设什么样的党,怎样建设党","C":"什么是社会主义,怎样建设社会主义","D":"中国特色社会主义"},"answer":"B","order":11,"explanation":"“三个代表”重要思想进一步回答了什么是社会主义、怎样建设社会主义的问题，创造性地回答了建设什么样的党、怎样建设党的问题。","note":""},{"id":12,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"下面关于毛泽东思想的论述,正确的选项是( )。","options":{"A":"毛泽东思想是毛泽东一个人的思想","B":"毛泽东思想也包括毛泽东同志晚年的错误思想","C":"毛泽东思想都是正确的","D":"毛泽东思想是被实践证明了的关于中国革命、建设、改革的正确的理论原则和经验总结。"},"answer":"D","order":12,"explanation":"毛泽东思想是马克思列宁主义在中国的运用和发展，是被实践证明了的关于中国革命和建设的正确的理论原则和经验总结，是中国共产党集体智慧的结晶。它不等于毛泽东个人全部思想，也不包括毛泽东晚年的错误。","note":"原题D项多写了“改革”，规范定义为“中国革命和建设”。为便于模拟原题，选项与答案字母D保留原文。"},{"id":13,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"中国特色社会主义理论体系不包括（）。","options":{"A":"邓小平理论","B":"科学发展观","C":"习近平新时代中国特色社会主义思想","D":"毛泽东思想"},"answer":"D","order":13,"explanation":"第二次历史性飞跃发生在社会主义进入改革开放的新时期，形成了包括邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想在内的中国特色社会主义理论体系。\n毛泽东思想是马克思主义中国化的第一个重大理论成果，是中国特色社会主义理论体系的重要思想渊源，不列为这一体系的组成部分。","note":""},{"id":14,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"马克思主义中国化时代化的理论成果是一脉相承又（ ）的关系。","options":{"A":"实事求是","B":"与时俱进","C":"独立自主","D":"精益求精"},"answer":"B","order":14,"explanation":"各理论成果是一脉相承又与时俱进的关系。一脉相承，体现共同的理论基础、立场观点方法和价值追求；与时俱进，体现各自回答不同时代和实践提出的新问题。","note":""},{"id":15,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"中国共产党一经诞生,就把为中国人民谋幸福、为中华民族谋复兴确立为自己的初心使命。一百年来,中国共产党团结带领中国人民进行的一切奋斗、一切牺牲、一切创造,归结起来就是一个主题( )","options":{"A":"实现共同富裕","B":"实现全面建成小康社会","C":"实现社会主义现代化","D":"实现中华民族伟大复兴"},"answer":"D","order":15,"explanation":"实现中华民族伟大复兴是近代以来中华民族最伟大的梦想。中国共产党一经成立，就把实现共产主义作为党的最高理想和最终目标，义无反顾肩负起实现中华民族伟大复兴的历史使命。\n本题的主题是实现中华民族伟大复兴。党的初心使命是为中国人民谋幸福、为中华民族谋复兴。","note":""},{"id":16,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"马克思主义中国化的科学内涵包括( )。","options":{"A":"联系中国实际运用马克思主义解决中国革命建设和改革中的问题","B":"运用马克思主义的立场、观点和方法来解决中国的实际问题","C":"把马克思主义植根于中国的优秀文化之中","D":"以上都是"},"answer":"D","order":16,"explanation":"（1）联系中国实际，运用马克思主义解决中国革命、建设和改革中的问题。\n（2）把中国实践经验加以总结，上升为理论，丰富和发展马克思主义。\n（3）把马克思主义植根于中国优秀文化之中，形成具有中国特色、中国风格、中国气派的理论成果。","note":""},{"id":17,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"（）明确把“不断谱写马克思主义中国化时代化新篇章”作为当代中国共产党人的庄严历史责任，并提出了继续推进马克思主义中国化时代化的新要求。","options":{"A":"党的十七大","B":"党的十八大","C":"党的十九大","D":"党的二十大"},"answer":"D","order":17,"explanation":"2022年召开的党的二十大，把不断谱写马克思主义中国化时代化新篇章作为当代中国共产党人的庄严历史责任，提出继续推进马克思主义中国化时代化的新要求。","note":""},{"id":18,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"被实践证明了的关于中国革命和建设的正确的理论原则和经验总结是( )。","options":{"A":"毛泽东思想","B":"邓小平理论","C":"科学发展观","D":"“三个代表”重要思想"},"answer":"A","order":18,"explanation":"这是毛泽东思想。其完整科学含义还包括：马克思列宁主义在中国的运用和发展、中国共产党集体智慧的结晶。","note":""},{"id":19,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"马克思主义中国化时代化提出的原因不包括( )。","options":{"A":"中国国情的特殊需要","B":"马克思主义理论的内在要求","C":"马克思主义指导作用的发挥必须结合各个国家的具体实际","D":"马克思主义是科学的理论"},"answer":"D","order":19,"explanation":"（1）这是解决中国实际问题的客观需要，中国具有自己的国情和历史任务。\n（2）这是马克思主义理论自身发展的内在要求，理论必须随实践和时代发展。\n（3）马克思主义指导作用的发挥，必须同各国具体实际相结合。","note":"注意本题问“不属于”。“马克思主义是科学的理论”本身是正确判断，但不构成本题所列的直接原因。"},{"id":20,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"邓小平理论鲜明的回答了( )这个首要的基本理论问题。","options":{"A":"发展生产力","B":"改革开放","C":"什么是社会主义,怎样建设社会主义","D":"中国特色社会主义"},"answer":"C","order":20,"explanation":"邓小平理论的基本问题是：什么是社会主义，怎样建设社会主义。","note":""},{"id":21,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"单选","question":"党的十八大以来，以习近平同志为核心的党中央明确提出要不断推进（）。","options":{"A":"社会主义现代化","B":"马克思主义中国化时代化","C":"“ 两个结合 ”","D":"社会主义现代化强国"},"answer":"B","order":21,"explanation":"党的十八大以来，强调不断推进马克思主义中国化时代化，使马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，不断回答中国之问、世界之问、人民之问、时代之问。","note":""},{"id":22,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"多选","question":"准确把握马克思主义中国化时代化的科学内涵，要做到坚持（）与（）相统一。","options":{"A":"马克思主义","B":"发展马克思主义","C":"社会主义","D":"中 国特色社会主义"},"answer":"AB","order":1,"explanation":"要坚持马克思主义与发展马克思主义相统一。坚持是发展的前提，发展是更好坚持的要求；既不能丢掉马克思主义基本原理，也不能把马克思主义当作僵化的教条。","note":""},{"id":23,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"多选","question":"“马克思主义中国化”成为中国共产党人重大时代课题的原因在于( )。","options":{"A":"马克思主义理论发展的内在要求","B":"人民群众的呼唤","C":"解决中国实际问题的客观需要","D":"共产国际的指示"},"answer":"AC","order":2,"explanation":"第一，是马克思主义理论发展的内在要求。第二，是解决中国实际问题的客观需要。必须在坚持马克思主义中发展马克思主义，在解决中国实际问题中推进理论创新。","note":""},{"id":24,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"多选","question":"坚持和发展马克思主义，必须（）。","options":{"A":"同中国具体实际相结合","B":"同中华优秀传统文化相结合","C":"同社会主义现代化发展相结合","D":"同中华民族伟大复兴相结合"},"answer":"AB","order":3,"explanation":"必须把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合。这就是“两个结合”。","note":""},{"id":25,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"多选","question":"实践证明，中国共产党为什么能，中国特色社会主义为什么好，归根到底是（）。","options":{"A":"马克思主义经典作家行","B":"科学社会主义行","C":"马克思主义行","D":"中国化时代化的马克思主义行"},"answer":"CD","order":4,"explanation":"归根到底是马克思主义行，是中国化时代化的马克思主义行。关键在于以科学理论为指导，并把科学理论同中国实际和时代发展结合起来。","note":""},{"id":26,"chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","type":"多选","question":"中国共产党人对待马克思主义的科学态度不是( )。","options":{"A":"实事求是","B":"教条主义","C":"经验主义","D":"主观主义"},"answer":"BCD","order":5,"explanation":"实事求是，就是一切从实际出发，理论联系实际，坚持在实践中检验真理和发展真理。\n对待马克思主义要坚持实事求是，反对教条主义、经验主义和主观主义。不能照搬书本，也不能把局部经验当作普遍真理。","note":"本题问“不是什么科学态度”，题库答案为BCD。科学的态度应是实事求是。"},{"id":27,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"中国共产党区别于其他一切政党的根本标志是()。","options":{"A":"群众路线","B":"实事求是","C":"全心全意为人民服务","D":"独立自主"},"answer":"C","order":1,"explanation":"全心全意为人民服务是中国共产党的根本宗旨，也是中国共产党区别于其他一切政党的根本标志。党的一切工作必须以最广大人民的根本利益为出发点和落脚点。","note":""},{"id":28,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"中国革命和建设的基本立足点是()。","options":{"A":"独立自主,自力更生","B":"对内改革,对外开放","C":"解放思想,实事求是","D":"从中国实际出发,向外国学习"},"answer":"A","order":2,"explanation":"独立自主，就是坚持独立思考，走自己的路，就是坚定不移地维护民族独立、捍卫国家主权，把立足点放在依靠自己力量的基础上，同时积极争取外援，开展国际经济文化交流，学习国外一切对我们有益的先进事物。独立自主是中华民族的优良传统，是中国共产党、中华人民共和国立党立国的重要原则。\n本题直接结论：中国革命和建设的基本立足点是独立自主、自力更生。","note":""},{"id":29,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"毛泽东的建党学说特别注重()。","options":{"A":"制度建党","B":"组织入党","C":"批评与自我批评","D":"思想建党"},"answer":"D","order":3,"explanation":"毛泽东的建党学说特别注重思想建党，强调把思想建设放在党的建设首位。在农民和其他小资产阶级成分较多的条件下，要用无产阶级思想克服各种非无产阶级思想，保持党的无产阶级先锋队性质。","note":""},{"id":30,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"统一战线是中国共产党的基本策略原则,而中国共产党坚持和发展统一战线的基础是()。","options":{"A":"有理、有力、有节","B":"又联合又斗争","C":"坚持反倾向斗争","D":"工农联盟"},"answer":"D","order":4,"explanation":"工农联盟是中国共产党坚持和发展统一战线的基础。无产阶级必须依靠农民这一最可靠的同盟军，在巩固工农联盟的基础上争取和团结其他可以团结的力量。","note":""},{"id":31,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"毛泽东提出新民主主义革命的基本思想是在()。","options":{"A":"解放战争时期","B":"第一国内革命战争时期","C":"抗日战争时期","D":"土地革命战争时期"},"answer":"B","order":5,"explanation":"在第一次国内革命战争时期，即大革命时期，毛泽东通过《中国社会各阶级的分析》《湖南农民运动考察报告》等著作，分析中国社会各阶级，强调农民问题和无产阶级领导权，提出新民主主义革命的基本思想。","note":""},{"id":32,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"以毛泽东为代表的中国共产党人初步开辟了农村包围城市、武装夺取政权革命道路是在()。","options":{"A":"国民革命战争时期","B":"土地革命战争时期","C":"抗日战争时期","D":"解放战争时期"},"answer":"B","order":6,"explanation":"新民主主义革命的道路是农村包围城市、武装夺取政权。这是由中国所处的时代特点和具体国情决定的。\n这条道路是在土地革命战争时期初步开辟的。1927年秋收起义后，毛泽东转向农村，创建井冈山革命根据地，逐步探索中国革命的新道路。","note":""},{"id":33,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"中国共产党一切工作的根本路线是()。","options":{"A":"思想路线","B":"群众路线","C":"组织路线","D":"政治路线"},"answer":"B","order":7,"explanation":"群众路线，就是一切为了群众，一切依靠群众，从群众中来，到群众中去，把党的正确主张变为群众的自觉行动。\n群众路线是中国共产党一切工作的根本路线。","note":""},{"id":34,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"中国革命战争在长时期内的主要作战形式是()。","options":{"A":"游击战","B":"阵地战","C":"游击战和运动战","D":"游击战和阵地战"},"answer":"C","order":8,"explanation":"中国革命战争在长时期内的主要作战形式是游击战和运动战。应根据敌我力量、战争阶段和具体条件灵活运用，发挥人民战争的优势。","note":""},{"id":35,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"1937年,毛泽东对党的思想路线作了系统哲学论证的著作是() 。","options":{"A":"《反对本本主义》《改造我们的学习》","B":"《古田会议决议》","C":"《实践论》《矛盾论》","D":"《改造我们的学习》《矛盾论》"},"answer":"C","order":9,"explanation":"1937年，毛泽东在《实践论》和《矛盾论》中，从认识论和辩证法角度总结中国革命经验，对党的实事求是思想路线作了系统的哲学论证。","note":""},{"id":36,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"新民主主义革命的主体是()。","options":{"A":"农民","B":"资产阶级","C":"无产阶级","D":"半无产阶级"},"answer":"A","order":10,"explanation":"农民是新民主主义革命的主体和主力军，是无产阶级最可靠的同盟军。中国革命的基本问题是农民问题，无产阶级必须通过解决农民土地问题等方式建立巩固的工农联盟。","note":""},{"id":37,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"我们一切路线、方针、政策的制定仍应牢牢立足()这个最大实际,充分体现其必然要求。","options":{"A":"主要矛盾","B":"基本国情","C":"社会性质","D":"根本制度"},"answer":"B","order":11,"explanation":"我国仍处于并将长期处于社会主义初级阶段的基本国情没有变；我国是世界上最大发展中国家的国际地位没有变。\n制定路线、方针、政策必须牢牢立足我国基本国情这一最大实际，尤其要立足我国仍处于并将长期处于社会主义初级阶段的实际。","note":""},{"id":38,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"已经包含了毛泽东思想的活的灵魂的实事求是、群众路线、独立自主三个方面的基本因子的著作是:","options":{"A":"《星星之火,可以燎原》","B":"《反对本本主义》","C":"《矛盾论》、《实践论》","D":"《新民主主义论》"},"answer":"B","order":12,"explanation":"1930年写作的《反对本本主义》，已经包含实事求是、群众路线、独立自主三个方面的基本因子。该文强调调查研究，反对脱离实际、照抄书本的教条主义。","note":""},{"id":39,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"毛泽东思想形成和发展的时代背景是()。","options":{"A":"中国沦为半殖民地半封建社会","B":"帝国主义战争和无产阶级革命","C":"第一次世界大战的爆发","D":"中国工人阶级的成长壮大"},"answer":"B","order":13,"explanation":"帝国主义战争和无产阶级革命成为时代主题，是毛泽东思想形成和发展的时代背景。俄国十月革命开辟了世界无产阶级社会主义革命的新时代，为中国革命带来新的思想和历史条件。","note":""},{"id":40,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"马克思主义中国化第一次历史性飞跃的理论成果是()。","options":{"A":"毛泽东思想","B":"邓小平理论","C":"科学发展观","D":"习近平新时代中国特色社会主义思想"},"answer":"A","order":14,"explanation":"第一次历史性飞跃发生在新民主主义革命时期，形成了毛泽东思想。","note":""},{"id":41,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"中国从新民主主义向社会主义的过渡()。","options":{"A":"坚持工业和农业两条腿走路","B":"核心是正确处理人民内部矛盾","C":"采取社会主义工业化和社会主义改造并举的方针","D":"中心是解决农民的土地问题"},"answer":"C","order":15,"explanation":"采取社会主义工业化和社会主义改造同时并举的方针。在逐步实现国家社会主义工业化的同时，逐步实现对农业、手工业和资本主义工商业的社会主义改造，使建设与改造相互促进。","note":""},{"id":42,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"毛泽东思想形成和发展的实践基础是()。","options":{"A":"人民战争","B":"社会主义建设","C":"土地革命","D":"中国共产党领导人民进行革命和建设的成功实践"},"answer":"D","order":16,"explanation":"中国共产党领导人民进行革命和建设的成功实践，是题库所列的实践基础。完整理解还应包括党领导人民进行革命和建设所积累的正反两方面历史经验，既总结成功，也吸取失败的教训。","note":"原题仅写“成功实践”。理解时还应注意，毛泽东思想是中国革命和建设正反两方面历史经验的总结。"},{"id":43,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"毛泽东创造性地发展了马克思主义关于社会发展基本矛盾的学说,指出了社会主义社会()。","options":{"A":"存在着和阶级社会一样的矛盾","B":"矛盾消失了","C":"基本矛盾仍然是生产关系和生产力之间的矛盾、上层建筑和经济基础之间的矛盾","D":"主要是无产阶级和资产阶级的矛盾"},"answer":"C","order":17,"explanation":"社会主义社会的基本矛盾仍然是生产关系和生产力之间的矛盾、上层建筑和经济基础之间的矛盾。这些矛盾具有与旧社会不同的性质和特点，可以通过社会主义制度本身不断得到解决。","note":""},{"id":44,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"概括毛泽东思想活的灵魂的文献是()。","options":{"A":"《反对本本主义》","B":"《论人民民主专政》","C":"《中国共产党中央委员会关于建国以来党的若干历史问题的决议》","D":"《人的正确思想是从哪里来的》"},"answer":"C","order":18,"explanation":"毛泽东思想活的灵魂是实事求是、群众路线、独立自主。\n1981年党的十一届六中全会通过的《关于建国以来党的若干历史问题的决议》，把贯穿毛泽东思想各组成部分的立场、观点和方法概括为实事求是、群众路线、独立自主。","note":""},{"id":45,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"“ 人民，只有人民，才是创造世界历史的动力。 ” 这句话表达毛泽东思想活的灵魂是（ ）","options":{"A":"群众路线","B":"统一战线","C":"实事求是","D":"独立自主"},"answer":"A","order":19,"explanation":"群众路线，就是一切为了群众，一切依靠群众，从群众中来，到群众中去，把党的正确主张变为群众的自觉行动。\n这句话体现了人民群众是历史创造者的观点，对应毛泽东思想活的灵魂中的群众路线。","note":""},{"id":46,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"毛泽东思想的初步形成是在()。","options":{"A":"解放战争时期","B":"土地革命战争时期","C":"第一次国内革命战争时期","D":"抗日战争时期"},"answer":"B","order":20,"explanation":"毛泽东思想初步形成于土地革命战争时期，主要是20世纪20年代末、30年代初。农村包围城市、武装夺取政权思想的提出，标志着毛泽东思想的初步形成。","note":""},{"id":47,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"经济工作和其他一切工作的生命线是()。","options":{"A":"思想政治工作","B":"组织建设工作","C":"作风建设工作","D":"军队建设工作"},"answer":"A","order":21,"explanation":"思想政治工作是经济工作和其他一切工作的生命线。它通过坚定政治方向、统一思想、凝聚力量和调动积极性，为各项工作提供思想保证和精神动力。","note":""},{"id":48,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"中国共产党的思想方法是()。","options":{"A":"全心全意为人民服务","B":"理论联系实际","C":"实事求是","D":"一切从实际出发"},"answer":"C","order":22,"explanation":"实事求是，就是一切从实际出发，理论联系实际，坚持在实践中检验真理和发展真理。\n本题所问的思想方法是实事求是。","note":""},{"id":49,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"毛泽东指出,在党与民主党派的关系上实行()。","options":{"A":"团结-批评-团结","B":"统筹兼顾,适当安排","C":"百花齐放,百家争鸣","D":"长期共存、互相监督"},"answer":"D","order":23,"explanation":"在中国共产党同民主党派的关系上，实行“长期共存、互相监督”的方针。共产党领导的多党合作有利于团结各方面力量，接受监督，共同推进社会主义建设。","note":""},{"id":50,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"开始形成了以毛泽东同志为核心的党的第一代中央领导集体的会议是()。","options":{"A":"遵义会议","B":"洛川会议","C":"六届六中全会","D":"中共七大"},"answer":"A","order":24,"explanation":"1935年1月召开的遵义会议，开始形成以毛泽东同志为核心的党的第一代中央领导集体。这次会议是党的历史上一个生死攸关的转折点。","note":""},{"id":51,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"毛泽东思想得到系统总结和多方面展开而趋于成熟是在()。","options":{"A":"国民革命战争时期","B":"土地革命战争时期","C":"抗日战争时期","D":"解放战争时期"},"answer":"C","order":25,"explanation":"毛泽东思想在土地革命战争后期和抗日战争时期得到系统总结和多方面展开而趋于成熟。本题单选对应“抗日战争时期”。新民主主义革命理论的系统阐述，是其成熟的重要标志。","note":""},{"id":52,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"把毛泽东思想写入中国共产党章程是在()。","options":{"A":"中共六届六中全会上","B":"中共七大上","C":"中共六大上","D":"中共七届二中全会上"},"answer":"B","order":26,"explanation":"1945年召开的党的七大，把毛泽东思想确立为党的指导思想并写入党章。要区分初步形成、走向成熟和确立指导地位三个不同节点。","note":""},{"id":53,"chapter":"第一章 毛泽东思想及其历史地位","type":"单选","question":"开辟了世界无产阶级社会主义革命新时代的伟大事件是()。","options":{"A":"俄国十月革命","B":"五四运动","C":"中国共产党建立","D":"中华人民共和国建立"},"answer":"A","order":27,"explanation":"1917年俄国十月革命开辟了世界无产阶级社会主义革命的新时代，使社会主义由理论变为现实，并推动了马克思主义在中国的传播。","note":""},{"id":54,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"毛泽东思想的科学内涵是()。","options":{"A":"马克思列宁主义在中国的运用和发展","B":"中国共产党集体智慧的结晶","C":"被实践证明了的关于中国革命和建设的正确的理论原则和经验总结","D":"毛泽东的思想"},"answer":"ABC","order":1,"explanation":"（1）马克思列宁主义在中国的运用和发展。\n（2）被实践证明了的关于中国革命和建设的正确的理论原则和经验总结。\n（3）中国共产党集体智慧的结晶。","note":""},{"id":55,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"第一次国内革命战争时期,毛泽东提出的新民主主义革命基本思想主要体现在以下()著作中。","options":{"A":"《星星之火,可以燎原》","B":"《中国社会各阶级的分析》","C":"《反对本本主义》","D":"《湖南农民运动考察报告》"},"answer":"BD","order":2,"explanation":"主要有《中国社会各阶级的分析》和《湖南农民运动考察报告》。这些著作分析革命的敌人和朋友，强调农民斗争的重要性，为新民主主义革命理论的形成作了准备。","note":""},{"id":56,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"毛泽东思想有多方面的丰富内容,除了关于新民主主义革命理论外,还包括()。","options":{"A":"社会主义革命和社会主义建设的理论","B":"革命军队建设和军事战略的理论","C":"思想政治工作和文化工作的理论","D":"政策和策略以及党的建设的理论"},"answer":"ABCD","order":3,"explanation":"（1）新民主主义革命理论。\n（2）社会主义革命和社会主义建设理论。\n（3）革命军队建设和军事战略的理论。\n（4）政策和策略的理论。\n（5）思想政治工作和文化工作的理论。\n（6）党的建设理论。","note":""},{"id":57,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"毛泽东思想成熟的突出表现是()。","options":{"A":"科学阐述了新民主主义革命的对象、动力、领导力量、性质和前途等基本问题","B":"提出了新民主主义革命的总路线","C":"制定了相应的经济、政治、文化纲领","D":"指明了新民主主义革命的具体目标"},"answer":"ABCD","order":4,"explanation":"新民主主义革命的性质是资产阶级民主主义革命。新民主主义革命在完成民主革命任务后，还要进入社会主义革命。\n（1）科学阐述新民主主义革命的对象、动力、领导力量、性质和前途。\n（2）提出新民主主义革命总路线。\n（3）制定相应的政治、经济和文化纲领。\n（4）指明新民主主义革命的具体目标。","note":""},{"id":58,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"标志着毛泽东思想初步形成的重要文章主要有()。","options":{"A":"《中国的红色政权为什么能够存在?》","B":"《井冈山的斗争》","C":"《星星之火可以燎原》","D":"《反对本本主义》"},"answer":"ABCD","order":5,"explanation":"主要有《中国的红色政权为什么能够存在？》《井冈山的斗争》《星星之火，可以燎原》和《反对本本主义》。这些著作围绕工农武装割据、农村革命根据地和独立探索中国革命道路展开。","note":""},{"id":59,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"体现毛泽东思想得到多方面展开而趋于成熟的著作主要有()。","options":{"A":"《新民主主义论》","B":"《矛盾论》、《实践论》","C":"《中国革命和中国共产党》、《论联合政府》","D":"《<共产党人>发刊词》"},"answer":"ABCD","order":6,"explanation":"主要有《实践论》《矛盾论》《〈共产党人〉发刊词》《中国革命和中国共产党》《新民主主义论》和《论联合政府》。这些著作从哲学、革命理论和政治纲领等方面系统总结中国革命经验。","note":""},{"id":60,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"毛泽东思想的历史地位主要表现为()。","options":{"A":"是马克思主义中国化的第一个重大理论成果","B":"是中国革命和建设的科学指南","C":"是中国共产党和中国人民宝贵的精神财富","D":"是新时期全党全国各族人民团结奋斗的共同思想基础"},"answer":"ABC","order":7,"explanation":"（1）马克思主义中国化的第一个重大理论成果。\n（2）中国革命和建设的科学指南。\n（3）中国共产党和中国人民宝贵的精神财富。","note":""},{"id":61,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"毛泽东思想继续得到发展是在()。","options":{"A":"国民革命时期","B":"土地革命时期","C":"解放战争时期","D":"中华人民共和国建立后"},"answer":"CD","order":8,"explanation":"毛泽东思想在解放战争时期和中华人民共和国成立以后继续发展，形成和发展了人民民主专政、社会主义改造、社会主义建设以及正确处理人民内部矛盾等理论。","note":""},{"id":62,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"1941年,毛泽东在《改造我们的学习》一文中明确地界定了实事求是的科学含义。其中“是”是指 ()。","options":{"A":"客观存在的一切事物","B":"客观事物的内部联系","C":"规律性","D":"我们去研究"},"answer":"BC","order":9,"explanation":"1941年，毛泽东在《改造我们的学习》中指出，“实事”是客观存在着的一切事物，“是”是客观事物的内部联系，即规律性，“求”是去研究。要通过研究把握客观规律。","note":""},{"id":63,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"正确认识毛泽东思想的历史地位和指导意义,必须科学评价毛泽东和毛泽东思想。这个问题的解决()。","options":{"A":"关系到怎样看待党和国家过去几十年奋斗和前进的历史","B":"关系到党的团结、国家的安定","C":"关系到党和国家未来的发展前途","D":"不仅有重要的历史意义,而且有重要的现实意义"},"answer":"ABCD","order":10,"explanation":"（1）关系到怎样看待党和国家过去几十年奋斗和前进的历史。\n（2）关系到党的团结和国家的安定。\n（3）关系到党和国家未来的发展前途。\n（4）既有重要历史意义，也有重要现实意义。必须把毛泽东思想同毛泽东晚年的错误区分开来。","note":""},{"id":64,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"毛泽东思想的活的灵魂之一――实事求是的基本要求是()。","options":{"A":"理论联系实际","B":"调查研究","C":"坚持在实践中检验真理和发展真理","D":"一切从实际出发"},"answer":"ACD","order":11,"explanation":"实事求是，就是一切从实际出发，理论联系实际，坚持在实践中检验真理和发展真理。","note":""},{"id":65,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"坚持一切从实际出发,就要()。","options":{"A":"从客观存在的事实出发","B":"全面地看问题,不能只见树木不见森林","C":"发展地看问题,不能静止地、僵化地看问题","D":"坚持自己的亲眼所见、亲耳所闻才是客观事实"},"answer":"ABC","order":12,"explanation":"实事求是，就是一切从实际出发，理论联系实际，坚持在实践中检验真理和发展真理。\n（1）从客观存在的事实出发，而不是从主观愿望出发。\n（2）全面地看问题，不能只见树木不见森林。\n（3）发展地看问题，不能静止地、僵化地看问题。","note":""},{"id":66,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"下列各项中,体现毛泽东思想在解放战争时期和新中国成立以后继续得到发展的有()。","options":{"A":"提出了人民民主专政理论","B":"提出了社会主义改造理论","C":"提出了两类矛盾的学说特别是正确处理人民内部矛盾的理论","D":"提出了把马列主义的基本原理同中国革命和建设的具体实际“第二次结合”"},"answer":"ABCD","order":13,"explanation":"（1）提出人民民主专政理论。\n（2）提出社会主义改造理论。\n（3）提出社会主义社会两类不同性质矛盾的学说，特别是正确处理人民内部矛盾的理论。\n（4）提出把马克思列宁主义基本原理同中国具体实际进行“第二次结合”，探索适合中国情况的社会主义建设道路。","note":"“第二次结合”指社会主义建设道路探索，不要同“第二次历史性飞跃”混同。"},{"id":67,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"下面关于毛泽东思想和中国特色社会主义理论体系关系的说法正确的是()。","options":{"A":"毛泽东思想是中国特色社会主义理论体系的重要思想渊源","B":"中国特色社会主义理论体系在新的历史条件下进一步丰富和发展了毛泽东思想","C":"毛泽东思想和中国特色社会主义理论体系都是马克思列宁主义在中国的运用和发展","D":"毛泽东思想为中国特色社会主义理论体系的形成奠定了理论基础"},"answer":"ABCD","order":14,"explanation":"（1）两者都是马克思列宁主义在中国的运用和发展。\n（2）毛泽东思想是中国特色社会主义理论体系的重要思想渊源，为其形成奠定理论基础。\n（3）中国特色社会主义理论体系在新的历史条件下进一步丰富和发展了毛泽东思想。\n（4）两者一脉相承、与时俱进。","note":""},{"id":68,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"毛泽东思想的活的灵魂是()。","options":{"A":"实事求是","B":"群众路线","C":"独立自主","D":"与时俱进"},"answer":"ABC","order":15,"explanation":"毛泽东思想活的灵魂是实事求是、群众路线、独立自主。","note":""},{"id":69,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"无产阶级及其政党要实现自己对同盟者的领导,必须具备的条件是()。","options":{"A":"率领被领导者向着共同的敌人作坚决斗争并取得胜利","B":"对同盟者采取“有理、有利、有节”的策略原则","C":"坚持独立自主的原则,对同盟者实行又联合又斗争的政策","D":"对被领导者给以物质利益,至少不损害其利益,同时给以政治教育"},"answer":"AD","order":16,"explanation":"第一，率领被领导者向共同敌人作坚决斗争并取得胜利。第二，给被领导者以物质利益，至少不损害其利益，同时给予政治教育。领导权要在实际斗争中争取和巩固。","note":""},{"id":70,"chapter":"第一章 毛泽东思想及其历史地位","type":"多选","question":"毛泽东认为,中国资产阶级包括()。","options":{"A":"大资产阶级(或买办资产阶级)","B":"城市小资产阶级","C":"民族资产阶级","D":"知识分子"},"answer":"AC","order":17,"explanation":"近代中国资产阶级主要包括大资产阶级，即买办资产阶级，以及民族资产阶级。二者的经济地位、同帝国主义和封建主义的关系不同，在革命中的政治态度也不同，必须区别对待。","note":""},{"id":71,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"区别新民主主义革命与旧民主主义革命的根本标志是( )","options":{"A":"革命对象不同","B":"革命指导思想不同","C":"革命前途不同","D":"革命领导权不同"},"answer":"D","order":1,"explanation":"新民主主义革命是由无产阶级领导的，旧民主主义革命是由资产阶级领导的。","note":""},{"id":72,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"新民主主义革命最基本的动力是( )","options":{"A":"工人和农民","B":"无产阶级","C":"贫农","D":"农民阶级"},"answer":"B","order":2,"explanation":"新民主主义革命的动力包括无产阶级、农民阶级、城市小资产阶级和民族资产阶级。\n其中，无产阶级是新民主主义革命最基本的动力，也是革命的领导力量。要同“农民是主力军”区分开来。","note":""},{"id":73,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"新民主主义革命的中心问题是( )","options":{"A":"无产阶级的领导权","B":"无产阶级同资产阶级的联盟","C":"民族资产阶级的领导权","D":"农民阶级的主力军地位"},"answer":"A","order":3,"explanation":"新民主主义革命的领导力量是无产阶级。\n无产阶级领导权是新民主主义革命的中心问题。能否坚持无产阶级领导，关系到革命的性质、道路和前途。","note":""},{"id":74,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"秋收起义失败后,毛泽东创建的( )革命根据地,把武装斗争的主攻方向首先指向农村","options":{"A":"井冈山","B":"湘鄂西","C":"中央","D":"百色"},"answer":"A","order":4,"explanation":"1927年秋收起义后，毛泽东创建井冈山革命根据地，把武装斗争的主攻方向转向农村。这成为探索农村包围城市、武装夺取政权革命道路的重要开端。","note":""},{"id":75,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"中国革命的首要对象是( )","options":{"A":"帝国主义","B":"封建主义","C":"资产阶级","D":"官僚资本主义"},"answer":"A","order":5,"explanation":"新民主主义革命的对象是帝国主义、封建主义和官僚资本主义。\n在这三个对象中，帝国主义是中国革命的首要对象。反对帝国主义、争取民族独立，是中国革命必须首先解决的重大任务。","note":""},{"id":76,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"包含着新民主主义革命和社会主义革命双重性质的经济政策是( )","options":{"A":"没收封建地主阶级的土地","B":"没收民族资本","C":"没收官僚垄断资本","D":"保护民族工商业"},"answer":"C","order":6,"explanation":"没收官僚垄断资本，既具有新民主主义革命性质，又具有社会主义革命性质。一方面，它反对同帝国主义、封建主义相联系的官僚资产阶级；另一方面，没收大资本并归新民主主义国家所有，又具有消灭资本主义私有制的社会主义革命性质。","note":""},{"id":77,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"近代中国革命以()为开端,进入新民主主义革命阶段","options":{"A":"中国共产党的成立","B":"辛亥革命","C":"戊戌变法","D":"五四运动"},"answer":"D","order":7,"explanation":"中国资产阶级民主革命进入新民主主义革命的标志是五四运动的爆发。","note":"五四运动发生于1919年。"},{"id":78,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"在同资产阶级的联盟中必须实行的方针是( )","options":{"A":"一切服从统一战线","B":"团结一批评一团结","C":"一切经过统一战线","D":"既联合又斗争"},"answer":"D","order":8,"explanation":"必须实行既联合又斗争的方针。对资产阶级能够参加革命的一面实行联合，对其动摇、妥协和反共倾向进行必要斗争；通过有原则的斗争巩固团结，保持无产阶级的独立性和领导权。","note":""},{"id":79,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"新民主主义革命的主力军是( )","options":{"A":"农民阶级","B":"小资产阶级","C":"民族资产阶级","D":"工人阶级"},"answer":"A","order":9,"explanation":"农民阶级是新民主主义革命的主力军，是无产阶级最可靠的同盟军。农民占中国人口的绝大多数，深受帝国主义和封建主义压迫，具有强烈的革命要求。","note":""},{"id":80,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"毛泽东系统阐述中国革命三大法宝的文章是( )","options":{"A":"《战争和战略问题》","B":"《<共产党人>发刊词》","C":"《星星之火,可以燎原》","D":"《井冈山的斗争》"},"answer":"B","order":10,"explanation":"（1）统一战线。\n（2）武装斗争。\n（3）党的建设。\n毛泽东在1939年的《〈共产党人〉发刊词》中系统阐述了统一战线、武装斗争和党的建设三个法宝。","note":""},{"id":81,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"无产阶级及其政党在统一战线中必须坚持的原则是( )","options":{"A":"一切服从统一战线","B":"坚决斗争","C":"独立自主","D":"一切经过统一战线"},"answer":"C","order":11,"explanation":"独立自主，就是坚持独立思考，走自己的路，就是坚定不移地维护民族独立、捍卫国家主权，把立足点放在依靠自己力量的基础上，同时积极争取外援，开展国际经济文化交流，学习国外一切对我们有益的先进事物。独立自主是中华民族的优良传统，是中国共产党、中华人民共和国立党立国的重要原则。\n本题所问的原则是独立自主。具体到统一战线，就是保持党在政治上、思想上和组织上的独立性，坚持无产阶级领导权。","note":""},{"id":82,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"中国红色政权能够存在与发展的根本原因是( )","options":{"A":"相当力量的正式红军的存在","B":"良好的群众基础","C":"共产党的正确领导","D":"中国是一个由多个帝国主义国家间接统治的政治经济发展不平衡的大国"},"answer":"D","order":12,"explanation":"根本原因是中国是一个由多个帝国主义国家间接统治、经济政治发展极端不平衡的半殖民地半封建大国。这种特殊国情为红色政权在部分农村地区产生、存在和发展提供了客观条件。","note":""},{"id":83,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"近代中国的社会性质是( )","options":{"A":"殖民地","B":"资本主义社会","C":"封建社会","D":"半殖民地半封建社会"},"answer":"D","order":13,"explanation":"近代中国革命是资产阶级民主革命。这种性质是由近代中国的社会性质和主要矛盾决定的。\n近代中国的社会性质是半殖民地半封建社会。这决定了革命首先要完成反帝反封建的民主革命任务。","note":""},{"id":84,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"中国新民主主义革命时期的统一战线包含着两个联盟。其中基本的、主要的联盟是( )","options":{"A":"工人阶级同农民、小资产阶级等其他劳动人民的联盟","B":"工人阶级同农民、小资产阶级和民族资产阶级的联盟","C":"工人阶级同可以合作的非劳动人民的联盟","D":"工人阶级同城市小资产阶级的联盟"},"answer":"A","order":14,"explanation":"基本的、主要的联盟，是工人阶级同农民、城市小资产阶级等其他劳动人民的联盟。其中工农联盟是基础。必须放手发展和加强这个联盟，才能巩固无产阶级的领导权。","note":""},{"id":85,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"毛泽东思想关于党的建设理论中,始终放在党的建设的首位的是( )","options":{"A":"保持党的优良作风","B":"加强党员的党性修养","C":"加强党的思想建设","D":"加强党的组织建设"},"answer":"C","order":15,"explanation":"把思想建设放在党的建设首位。要坚持马克思主义指导，加强党员思想教育，克服非无产阶级思想，保持党的先进性和无产阶级先锋队性质。","note":"本题考毛泽东建党理论中的思想建设，注意区分新时代党的建设中把政治建设摆在首位的语境。"},{"id":86,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"解决中国革命问题的基本前提是( )","options":{"A":"分清敌人和朋友","B":"认清中国国情","C":"坚持无产阶级领导权","D":"建立工农联盟"},"answer":"B","order":16,"explanation":"近代中国革命是资产阶级民主革命。这种性质是由近代中国的社会性质和主要矛盾决定的。\n基本前提是认清中国国情，尤其认清近代中国半殖民地半封建的社会性质。只有立足国情，才能正确判断革命的对象、任务、性质、动力和道路。","note":""},{"id":87,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"中国革命的首要问题是( )","options":{"A":"认清革命的性质","B":"认清革命发展前途","C":"认清革命的发展阶段","D":"认清革命的敌人和朋友"},"answer":"D","order":17,"explanation":"中国革命的首要问题是认清革命的敌人和朋友。必须运用阶级分析方法，分清哪些阶级是革命对象，哪些阶级是革命动力，哪些力量可以团结，才能制定正确的革命策略。","note":""},{"id":88,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"新民主主义革命的性质是( )","options":{"A":"旧式资产阶级民主主义革命","B":"无产阶级革命","C":"农民阶级革命","D":"新式的特殊的资产阶级民主主义革命"},"answer":"D","order":18,"explanation":"新民主主义革命是无产阶级领导的资产阶级民主革命。","note":""},{"id":89,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"人民军队的宗旨是( )","options":{"A":"把政治工作放在一切工作的首位","B":"坚持以马克思主义为指导","C":"坚持中国共产党对军队的绝对领导","D":"全心全意为人民服务"},"answer":"D","order":19,"explanation":"人民军队的根本宗旨是全心全意为人民服务。军队来自人民、依靠人民、服务人民，必须维护人民利益，保持同人民群众的血肉联系。","note":""},{"id":90,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"建设新型人民军队的根本原则是( )","options":{"A":"官兵平等","B":"广泛的思想政治工作","C":"坚持党对军队的绝对领导","D":"全心全意为人民服务"},"answer":"C","order":20,"explanation":"党对军队绝对领导是人民军队的建军之本、强军之魂。\n建设新型人民军队的根本原则是坚持党对军队的绝对领导。","note":""},{"id":91,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"新民主主义的政体是( )","options":{"A":"多党合作的政治协商制度","B":"民主集中制的人民代表大会制度","C":"各革命阶级的联合专政","D":"无产阶级专政"},"answer":"B","order":21,"explanation":"新民主主义国家的政体是民主集中制的人民代表大会制度。其国体是无产阶级领导的各革命阶级的联合专政，人民当家作主是国家制度的核心内容和基本准则。","note":""},{"id":92,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"新民主主义经济纲领中极具特色的一项内容是( )","options":{"A":"保护民族工商业","B":"没收封建地主阶级的土地归农民所有","C":"没收官僚垄断资本归新民主主义国家所有","D":"没收民族资本归新民主主义国家所有"},"answer":"A","order":22,"explanation":"保护民族工商业，是新民主主义经济纲领中极具特色的一项内容。新民主主义革命反对官僚资本主义，不是一般地消灭资本主义；对有利于国计民生的民族工商业予以保护。","note":""},{"id":93,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"抗日战争时期,中国共产党在敌后抗日根据地实行的土地政策是( )","options":{"A":"没收一切土地平均分配","B":"保持原有的土地状态","C":"减租减息","D":"没收地主土地分配给农民"},"answer":"C","order":23,"explanation":"实行减租减息的土地政策，即地主减租减息、农民交租交息。这一政策既减轻农民负担，又有利于团结地主阶级中赞成抗日的力量，巩固抗日民族统一战线。","note":""},{"id":94,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"中国革命的特点和优点是( )","options":{"A":"由中国共产党领导的人民战争","B":"以武装的革命反对武装的反革命","C":"以反帝反封建作为两大革命任务","D":"目标是争取民族独立、人民解放,最终实现国家繁荣富强"},"answer":"B","order":24,"explanation":"以武装的革命反对武装的反革命，是中国革命的特点和优点。中国内无民主制度、外无民族独立，反动统治依靠武力维持，革命必须以武装斗争作为主要斗争形式。","note":""},{"id":95,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"中国革命建立最广泛的统一战线不仅是必要的,而且是可能的,这种可能是由( )","options":{"A":"半殖民地半封建的中国社会交织在一起的诸多矛盾决定的","B":"中国革命的长期性、残酷性及其发展的不平衡性所决定的","C":"中国半殖民地半封建社会的阶级状况决定的","D":"战争与革命的时代主题决定的"},"answer":"A","order":25,"explanation":"这种可能性由半殖民地半封建中国社会交织在一起的诸多矛盾决定。不同阶级和阶层在不同历史条件下，都可能同主要敌人发生矛盾，从而存在团结和建立联盟的条件。","note":""},{"id":96,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"“统帅革命的资产阶级,联合革命的无产阶级,实行资产阶级民主革命。”这一观点的错误实质在于( )","options":{"A":"放弃无产阶级的领导权","B":"抹杀农民阶级的革命性","C":"夸大资产阶级的作用","D":"忽视武装斗争的重要性"},"answer":"A","order":26,"explanation":"新民主主义革命是由无产阶级领导的，旧民主主义革命是由资产阶级领导的。\n错误实质是放弃无产阶级领导权。新民主主义革命必须由无产阶级及其政党领导，不能把领导权交给资产阶级。","note":""},{"id":97,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"新民主主义革命的基本问题是( )","options":{"A":"武装斗争问题","B":"农民问题","C":"工农联盟问题","D":"无产阶级领导权问题"},"answer":"B","order":27,"explanation":"新民主主义革命的基本问题是农民问题，而农民问题的核心是土地问题。农民是革命主力军，只有解决农民的切身利益问题，才能充分发动农民、巩固工农联盟。","note":""},{"id":98,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"毛泽东所说的中国民族资产阶级“从娘肚子里带出来的老毛病”是指( )","options":{"A":"妥协性","B":"两面性","C":"软弱性","D":"动摇性"},"answer":"C","order":28,"explanation":"题目中的“老毛病”指民族资产阶级的软弱性。民族资产阶级一方面受到帝国主义和封建主义压迫，具有革命性；另一方面又同它们有联系，具有软弱性和妥协性。","note":""},{"id":99,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"新民主主义文化的特征是无产阶级领导的()文化","options":{"A":"共产主义","B":"民族的科学的大众的","C":"新民主主义","D":"社会主义"},"answer":"B","order":29,"explanation":"新民主主义文化是无产阶级领导的、民族的、科学的、大众的文化。民族的强调民族尊严、独立和中国作风；科学的强调反对封建思想和迷信；大众的强调为广大人民服务。","note":""},{"id":100,"chapter":"第二章 新民主主义革命理论","type":"单选","question":"中国民主主义革命经历了旧民主主义革命和新民主主义革命两个阶段,“旧”阶段转变到“新”阶段的根本标志是( )","options":{"A":"中国革命领导阶级的变化","B":"中国革命主要对象的变化","C":"中国革命基本性质的变化","D":"中国社会主要矛盾的变化"},"answer":"A","order":30,"explanation":"新民主主义革命是由无产阶级领导的，旧民主主义革命是由资产阶级领导的。","note":"根本区别看领导阶级；具体历史开端看1919年五四运动，两个问法要区分。"},{"id":101,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"近代中国社会的主要矛盾是( )","options":{"A":"封建主义和人民大众的矛盾","B":"帝国主义和中华民族的矛盾","C":"地主阶级和农民阶级的矛盾","D":"帝国主义和中华民族的矛盾是各种矛盾中最主要的矛盾"},"answer":"ABD","order":1,"explanation":"主要矛盾是帝国主义和中华民族的矛盾、封建主义和人民大众的矛盾。其中，帝国主义和中华民族的矛盾是各种矛盾中最主要的矛盾。","note":""},{"id":102,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"1938年11月,毛泽东在《战争和战略问题》中明确指出( )“共产党的任务,基本地不是经过长期合法斗争以进入起义和战争,也不是先占城市后取乡村,而是走相反的道路。”其依据是( )","options":{"A":"农民占人口绝大多数,是民主革命的主力军","B":"中国内无民主制度,外无民族独立","C":"无产阶级是革命的领导阶级","D":"敌人长期占据着中心城市,农村是其统治的薄弱环节"},"answer":"ABD","order":2,"explanation":"新民主主义革命的道路是农村包围城市、武装夺取政权。这是由中国所处的时代特点和具体国情决定的。\n具体依据是：（1）中国内无民主制度、外无民族独立，不能主要依靠长期合法斗争夺取政权；（2）农民占人口绝大多数，是民主革命主力军；（3）敌人长期占据中心城市，农村是其统治的薄弱环节。","note":""},{"id":103,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"正确处理统一战线中两个联盟的关系,必须做到( )","options":{"A":"尽可能扩大第二个联盟,团结一切可以团结的力量","B":"孤立大地主大资产阶级","C":"放手发展和加强工农联盟","D":"正确发挥两个联盟之间的相互作用,使它们相互促进"},"answer":"ACD","order":3,"explanation":"（1）放手发展和加强工农联盟，巩固基本的、主要的联盟。\n（2）尽可能扩大同可以合作的非劳动者的联盟，团结一切可以团结的力量。\n（3）正确发挥两个联盟的相互作用，使二者相互促进，巩固无产阶级领导权。","note":""},{"id":104,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"新民主主义经济纲领的主要内容是( )","options":{"A":"没收官僚资产阶级的垄断资本归新民主主义的国家所有","B":"保护民族工商业","C":"没收封建地主阶级的土地归农民所有","D":"没收外国在华资本归新民主主义的国家所有"},"answer":"ABC","order":4,"explanation":"（1）没收封建地主阶级的土地归农民所有。\n（2）没收官僚资产阶级的垄断资本归新民主主义的国家所有。\n（3）保护民族工商业。\n三项政策分别处理封建土地所有制、官僚资本和民族资本，不能混同。","note":""},{"id":105,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"中国革命走农村包围城市、武装夺取政权的道路,必须处理好( )三者之间的关系,在中国共产党的领导下,实现三者的密切结合和有机统一","options":{"A":"农村根据地建设","B":"土地革命","C":"武装斗争","D":"党的建设"},"answer":"ABC","order":5,"explanation":"土地革命、武装斗争、农村革命根据地建设。\n三者必须在中国共产党领导下密切结合、有机统一。土地革命是基本内容，武装斗争是主要形式，农村革命根据地是战略阵地。","note":""},{"id":106,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"近代中国无产阶级具有的自身特点和优点包括( )","options":{"A":"与农民有着天然的联系,便于结成工农联盟","B":"没有任何生产资料","C":"深受帝国主义、封建主义和资本主义的三重压迫,革命坚决彻底","D":"人数虽少,但很集中,便于组织"},"answer":"ACD","order":6,"explanation":"（1）深受帝国主义、封建主义和资本主义的三重压迫，革命坚决彻底。\n（2）人数虽少，但分布集中，便于组织和团结。\n（3）与农民有天然联系，便于同农民结成巩固的工农联盟。","note":""},{"id":107,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"新民主主义的文化,是民族的科学的大众的文化。其中“民族的”是指( )","options":{"A":"在形式和内容上有中国作风和中国气派","B":"反对帝国主义压迫,主张中华民族的尊严和独立","C":"为全民族90%以上的工农大众服务","D":"反对外来的资本主义文化"},"answer":"AB","order":7,"explanation":"“民族的”是指反对帝国主义压迫，主张中华民族的尊严和独立；在形式和内容上具有中国作风和中国气派。同时，应尊重其他民族文化，吸收其有益成果。","note":""},{"id":108,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"土地革命战争时期,毛泽东指出( )“一国之内,在四周白色政权的包围中,有一小块或若干小块红色政权的区域长期地存在,这是世界各国从来没有的事。这种奇事的发生,有其独特的原因。”这些原因是( )","options":{"A":"中国是多个帝国主义国家间接统治的经济政治发展极端不平衡的半殖民地半封建大国","B":"国民革命的政治影响及良好的群众基础","C":"党的领导的有力量及其政策的不错误","D":"全国革命形势的继续发展和相当力量的正式红军的存在"},"answer":"ABCD","order":8,"explanation":"（1）中国是经济政治发展极端不平衡、由多个帝国主义国家间接统治的半殖民地半封建大国，这是根本原因。\n（2）国民革命的政治影响和良好的群众基础。\n（3）全国革命形势继续向前发展。\n（4）相当力量的正式红军存在。\n（5）党的领导有力量，政策正确。","note":""},{"id":109,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"土地革命战争时期,中国红色政权能够存在与发展的主观条件有( )","options":{"A":"多个帝国主义国家间接统治的政治经济发展不平衡的半殖民地半封建的大国","B":"相当力量的正式红军的存在","C":"良好的群众基础","D":"党的领导的有力量及其政策的不错误"},"answer":"BD","order":9,"explanation":"主观条件主要有两项：第一，相当力量的正式红军存在；第二，中国共产党的领导有力量、政策正确。要同经济政治发展不平衡等客观条件区分。","note":""},{"id":110,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"中国共产党在中国革命中战胜敌人的三个法宝是( )","options":{"A":"统一战线","B":"党的建设","C":"武装斗争","D":"土地革命"},"answer":"ABC","order":10,"explanation":"（1）统一战线。\n（2）武装斗争。\n（3）党的建设。","note":""},{"id":111,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"民主主义革命和社会主义革命的关系是( )","options":{"A":"社会主义革命是新民主主义革命的必然趋势","B":"两个革命之间需要有一个资本主义的过渡阶段","C":"两个革命可以“毕其功于一役”","D":"新民主主义革命是社会主义革命的必要准备"},"answer":"AD","order":11,"explanation":"新民主主义革命的性质是资产阶级民主主义革命。新民主主义革命在完成民主革命任务后，还要进入社会主义革命。\n新民主主义革命是社会主义革命的必要准备，社会主义革命是新民主主义革命的必然趋势。两个阶段既相互区别，又紧密衔接，不能把二者混为一谈，也不能把二者割裂。","note":""},{"id":112,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"新民主主义革命的动力包括( )","options":{"A":"农民阶级","B":"工人阶级","C":"民族资产阶级","D":"城市小资产阶级"},"answer":"ABCD","order":12,"explanation":"新民主主义革命的动力包括无产阶级、农民阶级、城市小资产阶级和民族资产阶级。","note":""},{"id":113,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"中国革命统一战线中的两个联盟是( )","options":{"A":"工人阶级同农民、小资产阶级等其他劳动者之间的联盟","B":"工人阶级同可以合作的非劳动者之间的联盟","C":"工人阶级和小资产阶级的联盟","D":"工人阶级和农民阶级的联盟"},"answer":"AB","order":13,"explanation":"（1）工人阶级同农民、城市小资产阶级等其他劳动者的联盟，是基本的、主要的联盟。\n（2）工人阶级同可以合作的非劳动者的联盟，主要是同民族资产阶级的联盟。\n必须以第一个联盟为基础，巩固和扩大统一战线。","note":""},{"id":114,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"近代中国社会的阶级结构是“两头小中间大”,“两头”是指( )","options":{"A":"地主大资产阶级","B":"农民阶级","C":"城市小资产阶级","D":"无产阶级"},"answer":"AD","order":14,"explanation":"“两头”指无产阶级和地主大资产阶级。这两部分在总人口中所占比重较小；“中间”主要包括农民阶级、城市小资产阶级和民族资产阶级。","note":""},{"id":115,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"新民主主义政治纲领规定的新民主主义国家( )","options":{"A":"人民当家作主是国家制度的核心内容和基本准则","B":"国体是各革命阶级的联合专政","C":"各革命阶级的联合专政就是工农民主专政","D":"政体是民主集中制的人民代表大会制度"},"answer":"ABD","order":15,"explanation":"（1）国体是无产阶级领导的各革命阶级的联合专政。\n（2）政体是民主集中制的人民代表大会制度。\n（3）人民当家作主是国家制度的核心内容和基本准则。\n其目标是建立新民主主义共和国。","note":""},{"id":116,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"毛泽东指出,新民主主义革命对象包括( )","options":{"A":"帝国主义","B":"资产阶级","C":"官僚资本主义","D":"封建主义"},"answer":"ACD","order":16,"explanation":"新民主主义革命的对象是帝国主义、封建主义和官僚资本主义。","note":""},{"id":117,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"近代中国社会的阶级结构是“两头小中间大”,“中间”是指( )","options":{"A":"城市小资产阶级","B":"民族资产阶级","C":"无产阶级","D":"农民阶级"},"answer":"ABD","order":17,"explanation":"“中间”主要指农民阶级、城市小资产阶级和民族资产阶级。这些阶级和阶层人数众多，是无产阶级需要争取、团结的重要力量，其中农民是革命主力军。","note":""},{"id":118,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"新民主主义革命时期无产阶级实现领导权的历史经验是( )","options":{"A":"必须建立以工农联盟为基础的广泛的统一战线","B":"必须建立和发展人民的革命武装力量","C":"加强无产阶级政党的建设","D":"无产阶级在同资产阶级建立统一战线时,必须坚持独立自主的原则"},"answer":"ABCD","order":18,"explanation":"新民主主义革命的领导力量是无产阶级。\n（1）建立以工农联盟为基础的广泛统一战线。\n（2）在同资产阶级建立统一战线时坚持独立自主原则。\n（3）建立和发展人民的革命武装力量。\n（4）加强无产阶级政党的建设。","note":""},{"id":119,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"新民主主义革命就是“新式的特殊的资产阶级民主主义革命”,它的基本特点是( )","options":{"A":"它有新的领导阶级即无产阶级","B":"它有新的指导思想即马克恩主义","C":"它属于世界无产阶级革命性质","D":"它有了新的前途,经过新民主主义革命进而达到社会主义的目标"},"answer":"ABD","order":19,"explanation":"新民主主义革命是无产阶级领导的资产阶级民主革命。\n它具有新的领导阶级，即无产阶级；新的指导思想，即马克思主义；新的革命前途，即经过新民主主义革命走向社会主义。其反帝反封建的任务决定它仍属于资产阶级民主革命。","note":"原选项“马克恩主义”为明显笔误，应理解为“马克思主义”。选项保留原文。"},{"id":120,"chapter":"第二章 新民主主义革命理论","type":"多选","question":"中国共产党领导的武装斗争,实质上是在无产阶级领导下的农民战争,这是因为( )","options":{"A":"中国革命不同时期人民武装力量的主要成分是农民","B":"农民阶级是中国最为集中的、最为革命的先进阶级","C":"革命的领导者中国共产党是农民阶级的先锋队组织","D":"中国革命最广大的动力和革命队伍的主力军是农民"},"answer":"AD","order":20,"explanation":"（1）农民是中国革命最广大的动力和革命队伍的主力军。\n（2）中国革命各个时期人民武装力量的主要成分是农民。\n（3）农民战争必须接受无产阶级及其政党的领导，才能沿着正确方向取得胜利。","note":""},{"id":121,"chapter":"第三章 社会主义改造理论","type":"单选","question":"建国初期，我国社会主义国营经济建立的最主要途径和手段是","options":{"A":"没收民族资本","B":"没收帝国主义在华企业","C":"没收官僚资本","D":"没收地主阶级的土地和财产"},"answer":"C","order":1,"explanation":"主要通过没收官僚资本建立。官僚资本控制着国民经济的重要部门，将其收归人民国家所有，为社会主义国营经济的建立和壮大提供了重要基础。","note":""},{"id":122,"chapter":"第三章 社会主义改造理论","type":"单选","question":"从中华人民共和国成立到社会主义改造基本完成，是我国从新民主主义到社会主义的过渡时期，这一时期，个体经济向社会主义集体经济过渡的形式是","options":{"A":"国家资本主义经济","B":"私人资本主义经济","C":"合作社经济","D":"国营经济"},"answer":"C","order":2,"explanation":"采取合作社经济这一过渡形式。通过组织互助合作，把分散的个体劳动者逐步组织起来，发展集体生产，实现从个体经济向社会主义集体经济的转变。","note":""},{"id":123,"chapter":"第三章 社会主义改造理论","type":"单选","question":"1952年底，随着土地改革的基本完成，我国社会的主要矛盾已转变成","options":{"A":"帝国主义和中华民族的矛盾、封建主义和人民大众的矛盾","B":"人民大众同帝国主义、封建主义及其走狗国民党反动派残余的矛盾","C":"工人阶级同资产阶级的矛盾、社会主义道路同资本主义道路的矛盾","D":"人民日益增长的物质文化需要同落后的社会生产之间的矛盾"},"answer":"C","order":3,"explanation":"随着土地改革等民主革命遗留任务的完成，国内主要矛盾逐步转变为工人阶级同资产阶级的矛盾、社会主义道路同资本主义道路的矛盾。这为向社会主义过渡提出了新的历史任务。","note":""},{"id":124,"chapter":"第三章 社会主义改造理论","type":"单选","question":"中国社会主义改造和社会主义建设道路中一个十分突出的特殊问题是","options":{"A":"农业的社会主义改造问题","B":"民族资本主义工商业的社会主义改造问题","C":"农业的机械化问题","D":"一个落后的农业国的工业化问题"},"answer":"D","order":4,"explanation":"一个落后的农业国如何实现工业化，是我国社会主义改造和社会主义建设道路中十分突出的特殊问题。因此，必须把社会主义工业化同社会主义改造结合起来，逐步建立工业化基础。","note":""},{"id":125,"chapter":"第三章 社会主义改造理论","type":"单选","question":"我国在对资产阶级工商业实行社会主义改造的过程中，国家向私营企业投资入股，企业生产资料由国家和资本家共同所有，利润分配仍然实行“四马分肥”，国家向企业派出公方代表，与工人、资本家共同管理和改造企业，公方代表居领导地位。这时的企业性质","options":{"A":"属于半社会主义性质","B":"具有了社会主义因素","C":"仍然属于私营企业","D":"基本上属于社会主义国营性质"},"answer":"A","order":5,"explanation":"这种个别企业公私合营属于半社会主义性质。国家和资本家共同拥有生产资料，国家派公方代表参与并领导企业管理，利润仍按国家税收、企业公积金、职工福利费和资本家红利等方面分配。","note":"必须看清是仍实行“四马分肥”的个别企业公私合营，不能同全行业公私合营后的情况混淆。"},{"id":126,"chapter":"第三章 社会主义改造理论","type":"单选","question":"中国共产党对个体农业和手工业实行社会主义改造的方针是","options":{"A":"国家帮助，典型示范","B":"趁热打铁，积极领导","C":"积极领导，稳步前进","D":"自愿互利，国家帮助"},"answer":"C","order":6,"explanation":"基本方针是积极领导、稳步前进。通过适当的组织形式逐步引导劳动者走合作化道路，既发挥主动性，又尊重实际条件，避免急于求成。","note":""},{"id":127,"chapter":"第三章 社会主义改造理论","type":"单选","question":"毛泽东关于农业社会主义改造理论来源是","options":{"A":"斯大林的合作化理论","B":"列宁的合作化理论","C":"恩格斯的合作化理论","D":"马克思的合作化理论"},"answer":"B","order":7,"explanation":"列宁的合作化理论是重要理论来源。中国共产党将这一理论同中国农业和农民的实际相结合，探索了通过互助合作逐步实现农业社会主义改造的道路。","note":""},{"id":128,"chapter":"第三章 社会主义改造理论","type":"单选","question":"我国在手工业的社会主义改造过程中所办的手工业生产合作社属于","options":{"A":"社会主义性质","B":"半社会主义性质","C":"社会主义萌芽性质","D":"非社会主义性质"},"answer":"A","order":8,"explanation":"手工业生产合作社属于社会主义性质。通过合作社组织，手工业者由个体分散生产逐步转向集体生产，生产资料转为集体所有。","note":""},{"id":129,"chapter":"第三章 社会主义改造理论","type":"单选","question":"我国进入社会主义初级阶段的起点及剥削阶级和剥削制度被消灭的标志是","options":{"A":"中华人民共和国的成立","B":"社会主义改造的完成","C":"国民经济恢复任务的完成","D":"中共十三大的召开"},"answer":"B","order":9,"explanation":"1956年底，农业、手工业、资本主义工商业的社会主义改造基本完成，标志着社会主义制度在我国确立。我国社会主义初级阶段从1956年社会主义改造基本完成时开始。","note":""},{"id":130,"chapter":"第三章 社会主义改造理论","type":"单选","question":"关于社会主义过渡时期总路线错误的说法是","options":{"A":"实现社会主义工业化，农业、手工业和资本主义工商业的社会主义改造","B":"以中国特色社会主义为目标","C":"以单一的社会主义公有制和计划经济体制为目标","D":"过渡时期结束的标志是社会主义改造结束"},"answer":"B","order":10,"explanation":"从中华人民共和国成立到社会主义改造基本完成，是一个过渡时期。党在这一时期的总路线和总任务，是在一个相当长的时期内，逐步实现国家的社会主义工业化，并逐步实现国家对农业、手工业和资本主义工商业的社会主义改造。可概括为“一化三改”，目标是实现从新民主主义向社会主义的转变。","note":"本题问不正确的一项。B项把当时总路线表述为“以中国特色社会主义为目标”，混淆历史阶段。"},{"id":131,"chapter":"第三章 社会主义改造理论","type":"单选","question":"标志着资本主义工商业的社会主义改造已经基本完成是实现了","options":{"A":"生产责任制","B":"手工业合作社的建立","C":"农业合作化","D":"全行业公私合营"},"answer":"D","order":11,"explanation":"重要标志是1956年实行全行业公私合营。随着全行业公私合营的推进，资本主义工商业的所有制关系发生根本变化，社会主义改造基本完成。","note":""},{"id":132,"chapter":"第三章 社会主义改造理论","type":"单选","question":"1956年，社会主义改造基本完成以后，我国社会的主要矛盾是","options":{"A":"坚持思想基本原则和资产阶级自由化之间的矛盾","B":"人民日益增长的物质文化生活需要同落后的社会生产之间的矛盾","C":"社会主义道路和资本主义道路之间的矛盾","D":"工人阶级和资产阶级的矛盾"},"answer":"B","order":12,"explanation":"1956年党的八大指出，国内主要矛盾是人民对于建立先进工业国的要求同落后农业国现实之间的矛盾，是人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要状况之间的矛盾。主要任务是集中力量发展社会生产力，实现国家工业化。","note":"原题答案为B。选项“人民日益增长的物质文化需要同落后的社会生产之间的矛盾”这一规范表述在1981年历史决议中进一步明确；1956年八大的具体表述见参考知识点。"},{"id":133,"chapter":"第三章 社会主义改造理论","type":"单选","question":"我国对资本主义工商业改造创造了国家资本主义的各种形式，其高级形式是","options":{"A":"委托加工，计划订货","B":"统购包销","C":"公私合营","D":"经销、代销"},"answer":"C","order":13,"explanation":"国家资本主义的高级形式是公私合营，包括个别企业公私合营和全行业公私合营。改造采取由低级到高级、逐步过渡的形式。","note":""},{"id":134,"chapter":"第三章 社会主义改造理论","type":"单选","question":"过渡时期总路线的主体是","options":{"A":"国家的社会主义工业化","B":"个体农业的集体化","C":"私营经济的国有化","D":"对个体农业、手工业和资本主义工商业的改造"},"answer":"A","order":14,"explanation":"主体是国家的社会主义工业化；两翼是对农业、手工业和资本主义工商业的社会主义改造。工业化与改造同时并举、相互促进，体现发展生产力和变革生产关系的统一。","note":""},{"id":135,"chapter":"第三章 社会主义改造理论","type":"单选","question":"中国共产党对资本主义工商业进行社会主义改造的主要方式是","options":{"A":"和平赎买","B":"合作化","C":"公私合营","D":"统购统销"},"answer":"A","order":15,"explanation":"主要方式是和平赎买，即国家通过适当方式有偿地把资本家的生产资料转变为公有财产，和平地实现生产关系的深刻变革。","note":""},{"id":136,"chapter":"第三章 社会主义改造理论","type":"单选","question":"党在过渡时期总路线的实质是","options":{"A":"发展生产力","B":"改变生产资料的私有制","C":"消灭剥削阶级","D":"改造个体农民和手工业者"},"answer":"B","order":16,"explanation":"实质是使生产资料的社会主义所有制成为我国国家和社会的唯一经济基础，即通过社会主义改造，改变生产资料私有制，确立社会主义公有制。","note":"这是过渡时期总路线的历史表述，不能据此否定后来社会主义初级阶段公有制为主体、多种所有制经济共同发展的基本经济制度。"},{"id":137,"chapter":"第三章 社会主义改造理论","type":"单选","question":"在我国的过渡性质时期，民族资产阶级与工人阶级的矛盾性质是","options":{"A":"既有对抗性一面又有非对抗性的一面","B":"没有矛盾","C":"非对抗性的","D":"对抗性的"},"answer":"A","order":17,"explanation":"这一矛盾既有对抗性的一面，也有非对抗性的一面。民族资产阶级具有剥削工人的一面，也有接受工人阶级及其政党领导、拥护宪法和接受社会主义改造的一面，因此存在和平改造的条件。","note":""},{"id":138,"chapter":"第三章 社会主义改造理论","type":"单选","question":"制定我国第一个五年计划的依据是","options":{"A":"过渡时期的总路线","B":"实现国家工业化","C":"土地改革的完成","D":"国民经济的恢复和发展"},"answer":"A","order":18,"explanation":"依据党在过渡时期的总路线制定。第一个五年计划从1953年开始实施，到1957年完成，把社会主义工业化建设同社会主义改造结合起来。","note":""},{"id":139,"chapter":"第三章 社会主义改造理论","type":"单选","question":"新民主主义社会中，处于领导地位的经济成分是","options":{"A":"国营经济","B":"私人和国家资本主义经济","C":"个体经济","D":"合作社经济"},"answer":"A","order":19,"explanation":"社会主义性质的国营经济处于领导地位。它掌握国家经济命脉，是引导其他经济成分、推动国民经济恢复发展和向社会主义过渡的重要力量。","note":""},{"id":140,"chapter":"第三章 社会主义改造理论","type":"单选","question":"中国共产党提出由新民主主义社会和平过渡到社会主义社会的最初设想是","options":{"A":"中华人民共和国成立后","B":"“文化大革命”时期","C":"社会主义改造完成后","D":"民主革命时期"},"answer":"D","order":20,"explanation":"在民主革命时期，党已经提出民主革命胜利后由新民主主义逐步向社会主义转变的设想。新中国成立后，这一设想结合国情逐步具体化，并通过过渡时期总路线和社会主义改造付诸实践。","note":""},{"id":141,"chapter":"第三章 社会主义改造理论","type":"多选","question":"1952年党中央在酝酿过渡时期总路线时，毛泽东把实现向社会主义转变的设想，由建国之初的“先搞工业化建设”再一举过渡，改变为“建设和改造同时并举，逐步过渡”，这一改变原因和条件是：","options":{"A":"为了确定我国工业化建设的社会主义方向","B":"我国社会主义经济因素的不断增长和对资本主义经济的限制","C":"我国工业化建设取得了重大成就","D":"民主革命的遗留任务已经完成"},"answer":"ABD","order":1,"explanation":"（1）需要确保我国工业化建设沿着社会主义方向前进。\n（2）社会主义经济因素不断增长，对资本主义经济的限制逐步加强，提供了现实条件。\n（3）民主革命遗留任务已经完成，经济恢复取得成效，为进一步改造创造了条件。\n因此，采取建设和改造同时并举、逐步过渡的方针。","note":""},{"id":142,"chapter":"第三章 社会主义改造理论","type":"多选","question":"中国共产党根据马克思列宁主义关于农业社会主义改造的思想，从我国的实际出发，开创了一条有中国特点的农业合作化道路，成功实现了对个体农业的社会主义改造，其成功经验主要有","options":{"A":"实行“三级所有、队为基础”的农村集体经济体制","B":"采取从互助组到初级合作社到高级合作社的逐步过渡形式","C":"遵循自愿互利、典型示范、国家帮助的原则","D":"在土地改革基础上，不失时机地引导个体农民走互助合作道路"},"answer":"BCD","order":2,"explanation":"（1）在土地改革基础上，不失时机地引导个体农民走互助合作道路。\n（2）遵循自愿互利、典型示范和国家帮助的原则。\n（3）采取从互助组到初级农业生产合作社、再到高级农业生产合作社的逐步过渡形式。\n（4）坚持积极领导、稳步前进，正确处理生产发展与合作化的关系。","note":""},{"id":143,"chapter":"第三章 社会主义改造理论","type":"多选","question":"从中华人民共和国成立到社会主义改造基本完成，是我国从新民主主义到社会主义的过渡时期。这一时期中国社会的阶级构成主要包括","options":{"A":"工人阶级","B":"民族资产阶级","C":"城市小资产阶级","D":"农民阶级"},"answer":"ABCD","order":3,"explanation":"主要有工人阶级、农民阶级、城市小资产阶级和民族资产阶级。工人阶级处于领导地位；随着社会主义改造推进，其他阶级的经济地位和社会关系逐步发生变化。","note":""},{"id":144,"chapter":"第三章 社会主义改造理论","type":"多选","question":"我国社会主义改造是一场伟大的社会变革，但是在改造过程中也出现了一些偏差，遗留了一些问题，具体表现在","options":{"A":"所有制结构过于单一，在社会主义公有制已居于绝对统治地位的条件下，没有限度地保留一部分有益于国计民生的个体经济和私营经济","B":"要求过急，发展过快，工作过粗，改造形式过于简单","C":"高度集中的计划经济体制也随之扩大到整个社会经济生活","D":"在一定程度上排斥了商品经济和市场经济的正常运行"},"answer":"ABCD","order":4,"explanation":"（1）要求过急、工作过粗、改变过快，改造形式过于简单。\n（2）所有制结构过于单一，没有在适当限度内保留有益于国计民生的个体经济和私营经济。\n（3）高度集中的计划经济体制扩大到整个社会经济生活。\n（4）在一定程度上限制了商品经济和市场机制正常作用的发挥。","note":"原选项“没有限度地保留”语义有误，应结合上下文理解为“没有在适当限度内保留”。本网站保留原题选项和答案。"},{"id":145,"chapter":"第三章 社会主义改造理论","type":"多选","question":"关于中国新民主主义社会，下列说法正确的是","options":{"A":"它与社会主义初级阶段本质上是相同的","B":"就全国范围来讲，它是指从1949年中华人民共和国的成立到1956年社会主义改造的基本完成","C":"它是一个过渡性质的社会，类似于马克思列宁所说的过渡时期","D":"它从属于社会主义范畴"},"answer":"BCD","order":5,"explanation":"从中华人民共和国成立到社会主义改造基本完成这一时期，我国的社会性质是新民主主义社会。\n其时间范围一般为1949年至1956年。它是一个过渡性质的社会，既有社会主义因素，也有资本主义因素；社会主义因素居于领导地位，发展方向是社会主义，因而属于社会主义体系中的过渡阶段。","note":"“属于社会主义范畴”不等于1949年已确立社会主义基本制度，制度确立的标志仍是1956年三大改造基本完成。"},{"id":146,"chapter":"第三章 社会主义改造理论","type":"多选","question":"我国对资本主义工商业进行社会主义改造的经验有","options":{"A":"对私人资本主义的赎买政策应始终坚持“四马分肥”","B":"严格区别官僚资本和民族资本的界限，实行了和平赎买，和平地实现了和平关系的深刻变革","C":"把对企业的改造和对资本家的改造结合起来，把资本家改造成自食其力的劳动者","D":"创造了国家资本主义的多种形式，采取了由低级到高级逐步过渡的形势"},"answer":"BCD","order":6,"explanation":"（1）严格区别官僚资本和民族资本，对民族资本实行和平赎买，和平地实现生产关系的深刻变革。\n（2）创造国家资本主义的多种形式，采取由低级到高级逐步过渡的形式。\n（3）把对企业的改造同对资本家的改造结合起来，把资本家改造为自食其力的劳动者。","note":"原选项“和平关系”“过渡的形势”为笔误，应理解为“生产关系”“过渡的形式”。本网站保留原题选项和答案。"},{"id":147,"chapter":"第三章 社会主义改造理论","type":"多选","question":"新中国对民族资产阶级实行和平赎买的必要性在于","options":{"A":"中国经济落后，需要利用民族资本主义经济有利于国计民生的一面","B":"民族资产阶级有一定的技术专长和管理经验","C":"民族资产阶级经济实力雄厚，掌握国家经济命脉","D":"民族资产阶级经济构成整个国民经济的基础"},"answer":"AB","order":7,"explanation":"（1）中国经济落后，需要利用民族资本主义经济中有利于国计民生的一面，保持和发展生产。\n（2）民族资产阶级拥有一定技术专长和管理经验，和平赎买有利于利用这些能力。\n（3）这种方式有利于减少改造阻力，维护社会稳定，实现生产关系的和平变革。","note":""},{"id":148,"chapter":"第三章 社会主义改造理论","type":"多选","question":"新中国对个体手工业社会主义改造的主要形式有","options":{"A":"供销合作社","B":"公私合营","C":"生产合作社","D":"供销组"},"answer":"ACD","order":8,"explanation":"主要经历手工业供销小组、手工业供销合作社、手工业生产合作社三个逐步过渡的组织形式。通过由低级到高级的合作化，把个体手工业经济改造为社会主义集体经济。","note":""},{"id":149,"chapter":"第三章 社会主义改造理论","type":"多选","question":"在新民主主义社会中，主要的经济成分有哪几种","options":{"A":"合作社经济","B":"个体经济","C":"社会主义经济","D":"资本主义经济"},"answer":"BCD","order":9,"explanation":"主要经济成分是社会主义经济、个体经济和资本主义经济。如果按全部经济形式列举，还包括合作社经济和国家资本主义经济两种过渡形式。社会主义经济处于领导地位。","note":"本题问“主要经济成分”应答三种；若问“五种经济成分”，则需把两种过渡形式也列出。"},{"id":150,"chapter":"第三章 社会主义改造理论","type":"多选","question":"上世纪50年代，我国在对资本主义工商业进行社会主义改造过程中创造的国家资本主义的具体形式有","options":{"A":"经销代销","B":"统购包销","C":"加工订货","D":"公私合营"},"answer":"ABCD","order":10,"explanation":"具体形式包括加工订货、统购包销、经销代销和公私合营等。加工订货、统购包销、经销代销等属于低级形式；公私合营属于高级形式。","note":""},{"id":151,"chapter":"第五章 邓小平理论","type":"单选","question":"台湾问题性质不同于香港问题和澳门问题,台湾问题的实质是( )。","options":{"A":"历史上殖民主义侵略遗留下来的问题","B":"中国与美国的关系问题","C":"中国与日本的关系问题","D":"中国的内政问题"},"answer":"D","order":1,"explanation":"按照课程教材的表述，台湾问题是中国内战遗留下来的问题，实质是中国的内政问题。它同历史上殖民占领造成的香港、澳门问题性质不同。","note":""},{"id":152,"chapter":"第五章 邓小平理论","type":"单选","question":"党和国家的生命线,人民的幸福线指是( )","options":{"A":"党的基本路线","B":"党的基本经验","C":"党的基本方略","D":"党的基本纲领"},"answer":"A","order":2,"explanation":"领导和团结全国各族人民，以经济建设为中心，坚持四项基本原则，坚持改革开放，自力更生，艰苦创业，为把我国建设成为富强、民主、文明的社会主义现代化国家而奋斗。\n党的基本路线是党和国家的生命线、人民的幸福线，指明社会主义初级阶段的奋斗方向和基本途径，必须长期坚持，把以经济建设为中心同四项基本原则、改革开放统一起来。","note":""},{"id":153,"chapter":"第五章 邓小平理论","type":"单选","question":"社会主义市场经济理论认为,计划经济与市场经济属于( )。","options":{"A":"不同的生产关系的范畴","B":"不同的经济制度的范畴","C":"不同的经济增长方式","D":"不同的资源配置方式"},"answer":"D","order":3,"explanation":"计划和市场都是经济手段，是不同的资源配置方式，不是区分社会主义与资本主义的根本标志。社会主义可以运用市场，资本主义也可以运用计划，关键是同什么社会基本制度相结合。","note":""},{"id":154,"chapter":"第五章 邓小平理论","type":"单选","question":"邓小平理论轮廓的形成标志是( )","options":{"A":"党十一届三中全会公报","B":"党十五大报告","C":"南方谈话","D":"党的十三大报告"},"answer":"D","order":4,"explanation":"党的十三大比较系统地论述了我国社会主义初级阶段理论，明确概括和全面阐发了党的基本路线。党的基本路线：“一个中心，两个基本点”，即以经济建设为中心，坚持四项基本原则，坚持改革开放。\n1987年党的十三大报告，第一次比较系统地概括中国特色社会主义理论的主要内容，标志着邓小平理论轮廓的形成。","note":""},{"id":155,"chapter":"第五章 邓小平理论","type":"单选","question":"建设中国特色社会主义,关键在于坚持、加强和改善( )","options":{"A":"国家发展战略","B":"社会主义市场经济","C":"党的领导","D":"基层群众自治"},"answer":"C","order":5,"explanation":"党的领导是中国特色社会主义最本质的特征，是中国特色社会主义制度的最大优势。\n建设中国特色社会主义，关键在于坚持、加强和改善党的领导。党的领导为事业发展提供根本政治保证。","note":""},{"id":156,"chapter":"第五章 邓小平理论","type":"单选","question":"“一个党,一个国家,一个民族,如果一切从本本出发,思想僵化,迷信盛行,那它就不能前进,它的生机就停止了,就要亡党亡国。”这句话要表达的是( )","options":{"A":"坚持改革开放","B":"坚持走社会主义道路","C":"中国还处在社会主义初级阶段","D":"坚持解放思想、实事求是"},"answer":"D","order":6,"explanation":"实事求是，就是一切从实际出发，理论联系实际，坚持在实践中检验真理和发展真理。\n解放思想，就是在马克思主义指导下打破习惯势力和主观偏见的束缚，研究新情况、解决新问题。解放思想和实事求是相统一，才能反对思想僵化和迷信书本，使主观认识符合客观实际。","note":""},{"id":157,"chapter":"第五章 邓小平理论","type":"单选","question":"邓小平理论形成的时代背景是( )","options":{"A":"和平与发展","B":"革命与战争","C":"开放融通","D":"合作共赢"},"answer":"A","order":7,"explanation":"和平与发展成为时代主题，是邓小平理论形成的时代背景。对时代主题的科学判断，为把工作重点转向经济建设、实行改革开放提供了重要依据。","note":""},{"id":158,"chapter":"第五章 邓小平理论","type":"单选","question":"中国共产党正式提出“邓小平理论”这一概念,深刻阐述了邓小平理论的历史地位和指导意义,进一步论述了邓小平对这一理论的创立做出了独创性贡献,并郑重地把“邓小平理论”同马克思主义、毛泽东思想一起,确立为党的指导思想写入党章的会议是( )。","options":{"A":"党的十三大","B":"党的十五大","C":"党的十六大","D":"党的十四大"},"answer":"B","order":8,"explanation":"1997年党的十五大正式提出“邓小平理论”这一概念，深刻阐述其历史地位和指导意义，把邓小平理论确立为党的指导思想并写入党章。","note":""},{"id":159,"chapter":"第五章 邓小平理论","type":"单选","question":"1992年党的十四大把建立社会主义市场经济体制作为我国经济体制改革的目标模式,是一次重大突破。这一重大突破的主要依据是( )。","options":{"A":"市场经济是由国家宏观调控的经济","B":"市场经济不具有制度属性","C":"市场经济在资源配置中起决定性作用","D":"市场经济是法治经济"},"answer":"B","order":9,"explanation":"重要理论依据是：市场经济作为资源配置方式，本身不具有区分社会主义和资本主义的制度属性。计划和市场都是经济手段，社会主义同市场经济可以结合。1992年党的十四大据此明确建立社会主义市场经济体制的改革目标。","note":"“市场经济不具有制度属性”应放在资源配置方式的意义上理解；社会主义市场经济仍同社会主义基本制度相结合。"},{"id":160,"chapter":"第五章 邓小平理论","type":"单选","question":"党的十三大系统论述了社会主义初级阶段理论。下列关于社会主义初级阶段理论说法不正确的是( )。","options":{"A":"我国已经进入社会主义社会,必须坚持而不能离开社会主义","B":"特指我国生产力落后,商品经济不发达条件下建设社会主义社会必然要经历的阶段","C":"我国的社会主义还处在不发达的阶段,必须正视而不能超越初级阶段","D":"任何国家进入社会主义都会经历的起始阶段"},"answer":"D","order":10,"explanation":"社会主义初级阶段，就是指我国在生产力落后、商品经济不发达条件下建设社会主义必然要经历的特定阶段，即从我国进入社会主义到基本实现社会主义现代化的整个历史阶段。\n社会主义初级阶段的论断包括两层含义：第一，我国已经进入社会主义社会，必须坚持而不能离开社会主义。第二，我国的社会主义社会还处在不发达的阶段，必须正视而不能超越初级阶段。","note":"本题为反向选择，D项错误。社会主义初级阶段特指我国在生产力落后、商品经济不发达条件下建设社会主义所经历的特定历史阶段。"},{"id":161,"chapter":"第五章 邓小平理论","type":"单选","question":"什么是社会主义、怎样建设社会主义,是邓小平在领导改革开放和现代化建设这一新的革命过程中,不断提出和反复思考的首要的基本的理论问题。搞清楚这个问题的关键是要( )。","options":{"A":"正确认识社会主义社会的发展动力","B":"正确认识社会主义的发展阶段","C":"在坚持社会主义基本制度的基础上进一步认清社会主义的本质","D":"正确认识社会主义市场经济"},"answer":"C","order":11,"explanation":"邓小平理论的基本问题是：什么是社会主义，怎样建设社会主义。\n关键是在坚持社会主义基本制度的基础上，进一步认清社会主义的本质。要把发展生产力与消灭剥削、消除两极分化、最终达到共同富裕统一起来。","note":""},{"id":162,"chapter":"第五章 邓小平理论","type":"单选","question":"社会主义的根本任务是( )","options":{"A":"阶级斗争","B":"发展生产力","C":"群众运动","D":"掌控意识形态领导权"},"answer":"B","order":12,"explanation":"社会主义的根本任务是发展生产力，完整表述为解放和发展社会生产力。只有不断发展生产力，才能增强综合国力、改善人民生活，为实现社会主义目标创造物质条件。","note":""},{"id":163,"chapter":"第五章 邓小平理论","type":"单选","question":"1992年党的十四大提出( )。","options":{"A":"计划和市场的内在统一","B":"要使市场在国家宏观调控下对资源配置起基础性作用","C":"在公有制基础上有计划的商品经济","D":"要使市场在资源配置中起决定性作用"},"answer":"B","order":13,"explanation":"1992年党的十四大提出，要使市场在国家宏观调控下对资源配置起基础性作用，并把建立社会主义市场经济体制确定为我国经济体制改革的目标。","note":"本题有明确的1992年历史限定，应答“基础性作用”，不要套用2013年十八届三中全会提出的“决定性作用”。"},{"id":164,"chapter":"第五章 邓小平理论","type":"单选","question":"邓小平理论是逐步形成和发展起来的。邓小平理论主题的形成是在( )。","options":{"A":"党的十二大上","B":"1992年的南方谈话中","C":"党的十三大上","D":"党的十一届三中全会上"},"answer":"A","order":14,"explanation":"十二大后，中国特色社会主义成为我们党全部理论和实践的主题。\n1982年党的十二大，邓小平提出“走自己的道路，建设有中国特色的社会主义”，成为邓小平理论主题形成的重要标志。","note":""},{"id":165,"chapter":"第五章 邓小平理论","type":"单选","question":"邓小平理论是逐步形成和发展起来的。邓小平理论逐步走向成熟是在( )。","options":{"A":"党的十一届三中全会上","B":"党的十三大上","C":"1992年的南方谈话中","D":"党的十二大上"},"answer":"C","order":15,"explanation":"1992年邓小平南方谈话，是邓小平理论逐步走向成熟的重要标志。南方谈话深刻阐述社会主义本质、计划和市场的关系、“三个有利于”等重大问题；随后党的十四大作了系统概括。","note":""},{"id":166,"chapter":"第五章 邓小平理论","type":"单选","question":"邓小平明确指出:“改革是中国的第二次革命。”所谓第二次革命,是与中国共产党领导的第一次革命相对而言的。社会主义改革的性质是( )。","options":{"A":"社会主义原有体制的修补","B":"社会主义基本制度的改革","C":"社会主义经济运行方式的改变","D":"社会主义制度的自我完善和发展"},"answer":"D","order":16,"explanation":"社会主义改革的性质是社会主义制度的自我完善和发展。改革要改变束缚生产力发展的体制和机制，解放和发展生产力，因其深刻性和广泛性被称为中国的第二次革命，但并不改变社会主义基本制度。","note":""},{"id":167,"chapter":"第五章 邓小平理论","type":"单选","question":"中国的发展离不开科学,邓小平深刻地概括为( )","options":{"A":"“三个有利于”的标准","B":"创新驱动发展战略","C":"科学技术是第一生产力","D":"科学兴国战略和人才强国战略"},"answer":"C","order":17,"explanation":"邓小平提出“科学技术是第一生产力”。科学技术能够渗透和作用于生产力各要素，推动生产工具、劳动者素质和生产组织方式进步，发展中国离不开科学技术。","note":""},{"id":168,"chapter":"第五章 邓小平理论","type":"单选","question":"党的基本路线高度概括了党在社会主义初级阶段的奋斗目标、基本途径和根本保证、领导力量和依靠力量以及实现这一目标的基本方针。“一个中心,两个基本点”是( )。","options":{"A":"基本途径","B":"基本方针","C":"奋斗目标","D":"依靠力量"},"answer":"A","order":18,"explanation":"党的十三大比较系统地论述了我国社会主义初级阶段理论，明确概括和全面阐发了党的基本路线。党的基本路线：“一个中心，两个基本点”，即以经济建设为中心，坚持四项基本原则，坚持改革开放。\n“一个中心、两个基本点”是实现社会主义初级阶段奋斗目标的基本途径，是基本路线最主要的内容。以经济建设为中心、坚持四项基本原则、坚持改革开放必须统一于中国特色社会主义实践。","note":""},{"id":169,"chapter":"第五章 邓小平理论","type":"单选","question":"我国发展生产力的目的是( )。","options":{"A":"改革开放","B":"共同富裕","C":"同步富裕","D":"解放生产力"},"answer":"B","order":19,"explanation":"社会主义的本质：解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕。\n科学内涵：第一，把解放和发展生产力纳入社会主义本质。第二，突出强调消灭剥削、消除两极分化，最终达到共同富裕。\n本题直接结论是最终达到共同富裕。发展生产力是实现这一目标的物质基础，不能把少数人富裕、两极分化当作社会主义的目标。","note":""},{"id":170,"chapter":"第五章 邓小平理论","type":"单选","question":"“一国两制”构想的提出者是( )。","options":{"A":"江泽民","B":"毛泽东","C":"周恩来","D":"邓小平"},"answer":"D","order":20,"explanation":"“一国两制”科学构想由邓小平提出。基本含义是在一个中国的前提下，国家主体坚持社会主义制度，同时允许特定地区按照统一安排保持原有资本主义制度和生活方式。","note":""},{"id":171,"chapter":"第五章 邓小平理论","type":"单选","question":"“和平统一、一国两制”构想的提出,最早是针对( )。","options":{"A":"澳门问题提出来的","B":"香港和澳门问题提出来的","C":"香港问题提出来的","D":"台湾问题提出来的"},"answer":"D","order":21,"explanation":"这一构想最早是针对解决台湾问题提出的，后来首先运用于解决香港问题和澳门问题。记忆时区分“最早针对台湾提出”与“首先在香港、澳门付诸实践”。","note":""},{"id":172,"chapter":"第五章 邓小平理论","type":"单选","question":"邓小平理论形成的现实依据是( )。","options":{"A":"我国改革开放和现代化建设的实践","B":"其他社会主义国家兴衰成败的历史经验","C":"和平与发展成为时代主题","D":"我国社会主义胜利和挫折的历史经验"},"answer":"A","order":22,"explanation":"我国改革开放和社会主义现代化建设的实践，是邓小平理论形成的现实依据。理论从实践中产生，又指导实践，并在新的实践中不断检验、丰富和发展。","note":""},{"id":173,"chapter":"第五章 邓小平理论","type":"单选","question":"全面改革进程中思想解放的科学总结是指( )","options":{"A":"《在武昌、深圳、珠海、上海等地的谈话要点》","B":"《坚持四项基本原则》","C":"《邓小平文选》二卷","D":"《解放思想,实事求,团结一致向前看》"},"answer":"A","order":23,"explanation":"1992年的《在武昌、深圳、珠海、上海等地的谈话要点》，即南方谈话，是全面改革进程中思想解放的科学总结。它进一步解放思想，推动改革开放和现代化建设进入新的阶段。","note":""},{"id":174,"chapter":"第五章 邓小平理论","type":"单选","question":"社会主义社会发展的直接动力是( )。","options":{"A":"发展生产力","B":"发展混合所有制经济","C":"发展科学技术","D":"改革"},"answer":"D","order":24,"explanation":"改革是社会主义社会发展的直接动力。通过改革不适应生产力发展要求的生产关系和上层建筑的某些环节，能够解放生产力、激发社会活力，推动社会主义制度完善和发展。","note":""},{"id":175,"chapter":"第五章 邓小平理论","type":"单选","question":"中国特色社会主义理论体系的开篇之作是( )。","options":{"A":"“三个代表”重要思想","B":"邓小平理论","C":"科学发展观","D":"毛泽东思想"},"answer":"B","order":25,"explanation":"邓小平作为中国特色社会主义理论的创立者，紧紧抓住“什么是社会主义、怎样建设社会主义”这个基本问题，明确提出“走自己的道路，建设有中国特色的社会主义”的伟大号召，从此，中国特色社会主义成为我们党全部理论和实践一以贯之的主题。它科学回答了建设中国特色社会主义的一系列基本问题，成功开创了中国特色社会主义。邓小平理论指导了改革开放的伟大实践。邓小平强调必须坚持以经济建设为中心，坚持四项基本原则，坚持改革开放，领导我们党制定了党在社会主义初级阶段的基本路线。我们党做出的这一切重大决策，把改革开放和社会主义现代化建设一步一步推向前进。","note":""},{"id":176,"chapter":"第五章 邓小平理论","type":"单选","question":"党的基本路线在改革开放实践中不断充实和完善,把“和谐”与“富强、民主、文明”一起写入基本路线的会议是( )。","options":{"A":"党的十五大","B":"党的十四大","C":"党的十六大","D":"党的十七大"},"answer":"D","order":26,"explanation":"2007年党的十七大，把“和谐”同“富强、民主、文明”一起写入基本路线，表述为建设富强民主文明和谐的社会主义现代化国家。基本路线的奋斗目标随实践发展不断充实。","note":""},{"id":177,"chapter":"第五章 邓小平理论","type":"单选","question":"党的十三大报告提出了党在社会主义初级阶段的基本路线,高度概括了党在社会主义初级阶段的奋斗目标。基本途径和根本保证、领导力量和依靠力量以及实现这一目标的基本方针。其中,实现社会主义初级阶段奋斗目标的根本立足点是( )。","options":{"A":"自力更生,艰苦创业","B":"解放思想,实事求是","C":"走自己的路,建设中国特色社会主义","D":"坚持四项基本原则,坚持改革开放"},"answer":"A","order":27,"explanation":"领导和团结全国各族人民，以经济建设为中心，坚持四项基本原则，坚持改革开放，自力更生，艰苦创业，为把我国建设成为富强、民主、文明的社会主义现代化国家而奋斗。\n根本立足点是自力更生、艰苦创业。必须立足自身力量，同时积极开展对外开放，吸收有益经验和成果。","note":""},{"id":178,"chapter":"第五章 邓小平理论","type":"单选","question":"邓小平和我们党对当代中国基本国情的科学判断是( )","options":{"A":"我国已经是发达社会主义","B":"中国特色社会主义进入新时代","C":"我国是最大的发展中国家","D":"我国正处于社会主义初级阶段"},"answer":"D","order":28,"explanation":"社会主义初级阶段，就是指我国在生产力落后、商品经济不发达条件下建设社会主义必然要经历的特定阶段，即从我国进入社会主义到基本实现社会主义现代化的整个历史阶段。\n社会主义初级阶段的论断包括两层含义：第一，我国已经进入社会主义社会，必须坚持而不能离开社会主义。第二，我国的社会主义社会还处在不发达的阶段，必须正视而不能超越初级阶段。","note":"我国正处于社会主义初级阶段，是本题的直接结论。进入新时代并未改变这一基本国情。"},{"id":179,"chapter":"第五章 邓小平理论","type":"单选","question":"邓小平在领导改革开放和现代化建设这一新的革命过程中,不断提出和反复思考的首要基本理论问题是( )。","options":{"A":"实现什么样的现代化、怎样实现现代化","B":"什么是社会主义、怎样建设社会主义","C":"建设什么样的党、怎样建设党","D":"实现什么样的发展、怎样发展"},"answer":"B","order":29,"explanation":"邓小平理论的基本问题是：什么是社会主义，怎样建设社会主义。","note":""},{"id":180,"chapter":"第五章 邓小平理论","type":"单选","question":"邓小平理论形成的历史根据是( )","options":{"A":"毛泽东思想","B":"社会主义建设的经验教训","C":"中华文明源远流长","D":"现代科学技术日新月异"},"answer":"B","order":30,"explanation":"社会主义建设的经验教训，是邓小平理论形成的历史根据。既包括我国社会主义建设正反两方面的经验，也包括苏联和其他社会主义国家的兴衰成败经验。","note":""},{"id":181,"chapter":"第五章 邓小平理论","type":"单选","question":"社会主义初级阶段是指( )。","options":{"A":"我国在生产力落后、商品经济不发达条件下建设社会主义必然要经历的特定历史阶段","B":"任何国家进入社会主义都会经历的起始阶段","C":"新民主主义社会向社会主义过渡的阶段","D":"资本主义向社会主义的过渡阶段"},"answer":"A","order":31,"explanation":"社会主义初级阶段，就是指我国在生产力落后、商品经济不发达条件下建设社会主义必然要经历的特定阶段，即从我国进入社会主义到基本实现社会主义现代化的整个历史阶段。\n社会主义初级阶段的论断包括两层含义：第一，我国已经进入社会主义社会，必须坚持而不能离开社会主义。第二，我国的社会主义社会还处在不发达的阶段，必须正视而不能超越初级阶段。","note":""},{"id":182,"chapter":"第五章 邓小平理论","type":"单选","question":"建设中国特色社会主义的总依据是( )","options":{"A":"社会主义改革开放理论","B":"社会主义本质理论","C":"社会主义初级阶段理论","D":"社会主义根本任务理论"},"answer":"C","order":32,"explanation":"社会主义初级阶段，就是指我国在生产力落后、商品经济不发达条件下建设社会主义必然要经历的特定阶段，即从我国进入社会主义到基本实现社会主义现代化的整个历史阶段。\n社会主义初级阶段的论断包括两层含义：第一，我国已经进入社会主义社会，必须坚持而不能离开社会主义。第二，我国的社会主义社会还处在不发达的阶段，必须正视而不能超越初级阶段。\n总依据是社会主义初级阶段。社会主义初级阶段理论揭示了我国的基本国情，为制定路线、方针、政策提供依据。","note":"原选项C写“社会主义初级阶段理论”，规范的“总依据”表述是“社会主义初级阶段”。本网站按原题答案C判分。"},{"id":183,"chapter":"第五章 邓小平理论","type":"单选","question":"邓小平理论活的灵魂、邓小平理论的精髓是( )。","options":{"A":"坚持四项基本原则","B":"解放思想、实事求是","C":"解放生产力,发展生产力","D":"坚持改革开放"},"answer":"B","order":33,"explanation":"毛泽东思想、邓小平理论的精髓是实事求是。\n题库本题采用的完整表述是“解放思想、实事求是”，原单选答案为B。解放思想与实事求是相统一，要求使思想认识符合实际、随着实践发展不断创新。","note":"本题按原题库选B：“解放思想、实事求是”。"},{"id":184,"chapter":"第五章 邓小平理论","type":"多选","question":"邓小平在1992年南方谈话中,对社会主义本质这一重大问题作了总结性的理论概括,澄清了不合乎社会发展规律和时代进步的模糊观念、摆脱了长期以来拘泥于具体模式而忽略社会主义本质的错误倾向,对于建设中国特色社会主义具有重大的理论意义和实践意义。邓小平关于社会主义本质的概括突出强调了( )。","options":{"A":"中国共产党的领导是中国特色社会主义最本质的特征","B":"消灭剥削、消除两极分化,最终达到共同富裕的发展目标","C":"解放和发展生产力在社会主义发展中的重要作用","D":"社会和谐是中国特色社会主义的本质属性"},"answer":"BC","order":1,"explanation":"社会主义的本质：解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕。\n科学内涵：第一，把解放和发展生产力纳入社会主义本质。第二，突出强调消灭剥削、消除两极分化，最终达到共同富裕。","note":""},{"id":185,"chapter":"第五章 邓小平理论","type":"多选","question":"邓小平在探索社会主义本质时( )。","options":{"A":"反复强调坚持四项基本原则","B":"将一些工具、手段性质的东西与社会主义剥离","C":"将关注点集中在发展生产力和实现共同富裕上","D":"认为社会主义和资本主义发展生产力的目的是一致的"},"answer":"ABC","order":2,"explanation":"社会主义的本质：解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕。\n科学内涵：第一，把解放和发展生产力纳入社会主义本质。第二，突出强调消灭剥削、消除两极分化，最终达到共同富裕。\n（1）反复强调坚持四项基本原则，守住社会主义基本制度。\n（2）把计划、市场等工具和手段，同社会主义的本质区别开来。\n（3）把关注点集中到发展生产力和实现共同富裕上。","note":""},{"id":186,"chapter":"第五章 邓小平理论","type":"多选","question":"“和平统一,一国两制”构想的基本内容有( )。","options":{"A":"两制并存","B":"港澳台高度自治","C":"一个中国","D":"港澳台是我国的特别行政区"},"answer":"ABCD","order":3,"explanation":"（1）坚持一个中国，这是构想的前提。\n（2）两种制度并存，国家主体坚持社会主义制度，特定地区保持原有资本主义制度。\n（3）在中央统一领导下实行高度自治。\n（4）通过特别行政区等制度安排实现和平统一。涉及台湾的特别行政区安排，是构想中的统一后安排。","note":"原选项“港澳台是我国的特别行政区”不能作为现实状态直接理解：香港、澳门已设特别行政区，关于台湾应理解为构想中的统一后安排。此题按原题答案判分。"},{"id":187,"chapter":"第五章 邓小平理论","type":"多选","question":"邓小平在南方谈话中指出:“社会主义本质是”( )","options":{"A":"实现现代化","B":"最终达到共同富裕","C":"消灭剥削,消除两极分化","D":"解放生产力,发展生产力"},"answer":"BCD","order":4,"explanation":"社会主义的本质：解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕。\n科学内涵：第一，把解放和发展生产力纳入社会主义本质。第二，突出强调消灭剥削、消除两极分化，最终达到共同富裕。","note":""},{"id":188,"chapter":"第五章 邓小平理论","type":"多选","question":"邓小平关于社会主义本质的论断体现了( )。","options":{"A":"目标与手段的统一","B":"解放生产力和发展生产力的统一","C":"生产力与生产关系的统一","D":"社会主义发展过程与发展目标的统一"},"answer":"ABCD","order":5,"explanation":"社会主义的本质：解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕。\n科学内涵：第一，把解放和发展生产力纳入社会主义本质。第二，突出强调消灭剥削、消除两极分化，最终达到共同富裕。\n（1）生产力与生产关系的统一。\n（2）解放生产力与发展生产力的统一。\n（3）目标与手段的统一。\n（4）社会主义发展过程与发展目标的统一。","note":""},{"id":189,"chapter":"第五章 邓小平理论","type":"多选","question":"邓小平理论形成的条件是( )","options":{"A":"社会主义建设的经验教训是邓小平理论形成的历史根据","B":"中国共产党历史方位的变化是邓小平理论形成的实践要求","C":"和平与发展成为时代主题是邓小平理论形成的时代背景","D":"改革开放和现代化建设的实践是邓小平理论形成的现实依据"},"answer":"ACD","order":6,"explanation":"（1）时代背景：和平与发展成为时代主题。\n（2）历史根据：社会主义建设的经验教训。\n（3）现实依据：我国改革开放和社会主义现代化建设的实践。\n三者分别回答时代条件、历史经验和实践来源。","note":""},{"id":190,"chapter":"第五章 邓小平理论","type":"多选","question":"实现社会主义本质的前提是( )。","options":{"A":"公有制的实现形式","B":"坚持共同富裕的目标","C":"维护公有制的主体地位","D":"维护按劳分配的主体地位"},"answer":"BCD","order":7,"explanation":"必须维护公有制的主体地位，维护按劳分配的主体地位，坚持共同富裕的目标。要在坚持社会主义基本制度的前提下解放和发展生产力，使发展成果惠及人民。","note":""},{"id":191,"chapter":"第五章 邓小平理论","type":"多选","question":"我国在社会主义建设初期走了不少弯路、犯了不少错误,其深层原因是( )","options":{"A":"经济上急于求成、盲目求纯和急于过渡","B":"偏离了党的实事求是的思想路线","C":"对什么是社会主义和如何建设社会主义的问题没有完全搞清楚","D":"在政治上坚持以阶级斗争为纲"},"answer":"BC","order":8,"explanation":"（1）必须把马克思主义与中国实际相结合，探索符合中国特点的社会主义建设道路。\n（2）必须正确认识社会主义社会的主要矛盾和根本任务，集中力量发展生产力。\n（3）必须从实际出发进行社会主义建设，建设规模和速度要和国力相适应，不能急于求成。\n（4）必须发展社会主义民主，健全社会主义法制。\n（5）必须坚持党的民主集中制和集体领导制度，加强执政党建设。\n（6）必须坚持对外开放，借鉴和吸收人类文明成果建设社会主义，不能关起门来搞建设。\n对应本题的深层原因主要有两项：一是偏离了实事求是的思想路线；二是对什么是社会主义、怎样建设社会主义没有完全搞清楚。","note":""},{"id":192,"chapter":"第五章 邓小平理论","type":"多选","question":"中国社会主义改革是( )。","options":{"A":"社会主义发展的直接动力","B":"当代中国最鲜明的特点","C":"社会主义制度的自我完善","D":"发展生产力的必由之路"},"answer":"ABCD","order":9,"explanation":"（1）改革是社会主义制度的自我完善和发展。\n（2）改革是社会主义社会发展的直接动力。\n（3）改革是解放和发展生产力的必由之路。\n（4）改革开放是当代中国最鲜明的特点，推动了社会各方面的深刻变化。","note":""},{"id":193,"chapter":"第五章 邓小平理论","type":"多选","question":"社会主义的根本任务是解放和发展生产力,其原因在于( )。","options":{"A":"高度发达的生产力是实现社会主义的物质基础","B":"解放和发展生产力是中国特色社会主义的根本任务","C":"解放和发展生产力是社会主义制度与资本主义制度相区别的根本标志","D":"解放生产力是为促进生产力的发展开辟道路"},"answer":"ABD","order":10,"explanation":"（1）高度发达的生产力是实现社会主义目标的物质基础。\n（2）解放和发展生产力体现社会主义本质，是中国特色社会主义的根本任务。\n（3）解放生产力是为生产力发展开辟道路，发展生产力为改善人民生活、最终达到共同富裕创造条件。","note":""},{"id":194,"chapter":"第五章 邓小平理论","type":"多选","question":"邓小平对时代主题的转变作出了科学判断,指出全球性战略问题有( )","options":{"A":"社会主义改革问题","B":"和平问题,也称东西问题","C":"环境保护与生态平衡问题","D":"发展问题,也称南北问题"},"answer":"BD","order":11,"explanation":"主要有和平问题与发展问题。和平问题通常称为东西问题，发展问题通常称为南北问题。解决和平与发展问题，需要维护国际和平环境，促进各国特别是发展中国家的发展。","note":""},{"id":195,"chapter":"第五章 邓小平理论","type":"多选","question":"邓小平理论形成的历史根据有( )。","options":{"A":"苏联社会主义建设的教训","B":"我国社会主义建设道路探索的经验","C":"其他社会主义国家兴衰成败的历史经验","D":"我国社会主义建设道路探索的教训"},"answer":"ABCD","order":12,"explanation":"包括我国社会主义建设道路探索的成功经验与挫折教训，也包括苏联社会主义建设的教训以及其他社会主义国家兴衰成败的历史经验。应同时总结国内外、正反两方面经验。","note":""},{"id":196,"chapter":"第五章 邓小平理论","type":"多选","question":"“以经济建设为中心”( )","options":{"A":"回答了社会主义的根本任务问题","B":"体现了发展生产力的本质要求","C":"是兴国之要","D":"是党和国家兴旺发达、长治久安的根本要求"},"answer":"ABCD","order":13,"explanation":"（1）以经济建设为中心，回答了社会主义根本任务的问题。\n（2）体现了解放和发展生产力的本质要求。\n（3）经济建设是兴国之要。\n（4）它是党和国家兴旺发达、长治久安的根本要求。必须把发展作为解决我国一切问题的基础和关键。","note":""},{"id":197,"chapter":"第五章 邓小平理论","type":"多选","question":"1978年12月召开的党的十一届三中全会,实现了党的历史上具有深远意义的伟大转折( )","options":{"A":"作出实行改革开放的重大决策","B":"停止使用“以阶级斗争为纲”的错误提法","C":"重新确立了解放思想、实事求是的思想路线","D":"确定把全党工作的着重点转移到社会主义现代化建设上来"},"answer":"ABCD","order":14,"explanation":"1978年12月召开的党的十一届三中全会，做出了实行改革开放的重大决策。\n（1）停止使用“以阶级斗争为纲”的错误提法。\n（2）重新确立解放思想、实事求是的思想路线。\n（3）把全党工作的着重点转移到社会主义现代化建设上来。\n（4）作出实行改革开放的重大决策，开启改革开放和社会主义现代化建设新时期。","note":""},{"id":198,"chapter":"第五章 邓小平理论","type":"多选","question":"1987年召开党的十三大指出:十一届三中全会以来,我们党在社会主义再认识的过程中,在哲学、政治经济学和科学社会主义等方面,拓展了一系列科学理论观点。党的十三大( )。","options":{"A":"提出了社会主义经济是公有制基础上的有计划的商品经济","B":"正式提出了“邓小平理论”这一概念","C":"第一次对中国特色社会主义理论进行系统的概括","D":"提出了社会主义初级阶段的基本路线"},"answer":"CD","order":15,"explanation":"党的十三大比较系统地论述了我国社会主义初级阶段理论，明确概括和全面阐发了党的基本路线。党的基本路线：“一个中心，两个基本点”，即以经济建设为中心，坚持四项基本原则，坚持改革开放。\n1987年党的十三大还第一次比较系统地概括了中国特色社会主义理论的主要内容，推动邓小平理论轮廓的形成。","note":""},{"id":199,"chapter":"第五章 邓小平理论","type":"多选","question":"邓小平理论的主要内容包括( )","options":{"A":"改革开放理论和社会主义市场经济理论","B":"党的基本路线和“三步走”战略","C":"“两手抓,两手都要硬”和“一国两制”","D":"社会主义初级阶段理论和社会主义根本任务理论"},"answer":"ABCD","order":16,"explanation":"党的十三大比较系统地论述了我国社会主义初级阶段理论，明确概括和全面阐发了党的基本路线。党的基本路线：“一个中心，两个基本点”，即以经济建设为中心，坚持四项基本原则，坚持改革开放。\n还包括社会主义根本任务理论、改革开放理论、社会主义市场经济理论、“三步走”发展战略、“两手抓，两手都要硬”的方针和“一国两制”构想。","note":""},{"id":200,"chapter":"第五章 邓小平理论","type":"多选","question":"判断改革和各方面工作的是非得失,归根到底,是要以____为标准。","options":{"A":"是否有利于发展社会主义社会的生产力","B":"是否有利于增强社会主义国家的综合国力","C":"是否有利于提高人民的生活水平","D":"是否增加了公有制经济的比重"},"answer":"ABC","order":17,"explanation":"（1）是否有利于发展社会主义社会的生产力。\n（2）是否有利于增强社会主义国家的综合国力。\n（3）是否有利于提高人民的生活水平。\n“三个有利于”体现把实践效果、国家发展和人民利益统一起来。","note":"这是第五章多选部分第17题，原文误编号为“1”，本网站按实际出现顺序排列。"}];
